export default JSON.parse("{\"schema\":\"ai-brain.semantic-merge.v1\",\"id\":\"ways-to-describe-emotions-anger-words-anger-bitterness-eb4ec9068fc8\",\"title\":\"Ways to Describe Emotions Anger Words anger bitterness\",\"domain\":\"dbt\",\"relatedDomains\":[\"dbt\"],\"purpose\":\"handout\",\"capabilities\":[\"dbt\",\"reference\",\"research\"],\"similarityReview\":{\"threshold\":0.75,\"pairScores\":[0.9965,0.8913,0.9377,0.8942,0.9344,0.8427],\"method\":\"5-token shingle Jaccard within same explicit purpose/title context\"},\"provenance\":{\"mergePolicy\":\"shared structure/content consolidated; unique list items/fields retained; scalar conflicts retained as _merged_values\",\"sources\":[{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/04-dbt-emotion-regulation-emotion-regulation-handout-6-ways-to-describe-emotions-anger-words-6d520c8973.json\",\"sha256\":\"6d520c8973a6ac38e309ed8b9af053a0c2d7a7f33e2be37f3ca62bca7810b10c\",\"domain\":\"dbt\",\"bytes\":56047},{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/emotion-regulation-handout-6-ways-to-describe-emotions-anger-words-anger-bitterness-27fc495ab4.json\",\"sha256\":\"27fc495ab459a78ee92679500b1982d8ad13d98848aa928c3a7dc2d82547512b\",\"domain\":\"dbt\",\"bytes\":55888},{\"sourcePath\":\"skills/skills/d148.json\",\"sha256\":\"6fd7fb095de508c009234877e1ea9a3d4839fe7c6d6275247c27bcb4596155e4\",\"domain\":\"dbt\",\"bytes\":60110},{\"sourcePath\":\"skills/skills/dbt/04_dbt_emotion_regulation_emotion_regulation_handout_6_ways_to_describe_emotions_anger_words_anger_26020865.json\",\"sha256\":\"0310ef1fb5c1ec75e9d36d43ede32f730670e1c86adfee819fd8d9b65717e653\",\"domain\":\"dbt\",\"bytes\":58905}]},\"data\":{\"pages\":[{\"pdf_page\":238,\"book_page\":\"214\",\"text\":\"214\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\n\u2610\\nEmotion Regulation Handout 6   (Emotion Regulation Worksheets 4, 4a) (p. 1 of 10)\\nWays to Describe Emotions\\nAnger Words\\nanger\\nbitterness\\nfury\\nindignation\\nvengefulness\\naggravation\\nexasperation\\ngrouchiness\\nirritation\\nwrath\\nagitation\\nferocity\\ngrumpiness\\noutrage\\nannoyance\\nfrustration\\nhostility\\nrage\\nPrompting Events for Feeling Anger\\n\u2022\u2022 Having an important goal blocked.\\n\u2022\u2022 You or someone you care about being\\nattacked or threatened by others.\\n\u2022\u2022 Losing power, status, or respect.\\n\u2022\u2022 Not having things turn out as expected.\\n\u2022\u2022 Physical or emotional pain.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Anger\\n\u2022\u2022 Believing that you have been treated unfairly.\\n\u2022\u2022 Blaming.\\n\u2022\u2022 Believing that important goals are being\\nblocked or stopped.\\n\u2022\u2022 Believing that things \u201cshould\u201d be different\\nthan they are.\\n\u2022\u2022 Rigidly thinking, \u201cI\u2019m right.\u201d\\n\u2022\u2022 Judging that the situation is illegitimate or\\nwrong.\\n\u2022\u2022 Ruminating about the event that set off the\\nanger in the first place.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Anger\\n\u2022\u2022 Muscles tightening.\\n\u2022\u2022 Teeth clamping together.\\n\u2022\u2022 Hands clenching.\\n\u2022\u2022 Feeling your face flush or get hot.\\n\u2022\u2022 Feeling like you are going to explode.\\n\u2022\u2022 Being unable to stop tears.\\n\u2022\u2022 Wanting to hit someone, bang the wall, throw\\nsomething, blow up.\\n\u2022\u2022 Wanting to hurt someone.\\n\u2022\u2022 Other:\\nExpressions and Actions of Anger\\n\u2022\u2022 Physically or verbally attacking.\\n\u2022\u2022 Making aggressive or threatening gestures.\\n\u2022\u2022 Pounding, throwing things, breaking things.\\n\u2022\u2022 Walking heavily, stomping, slamming doors.\\n\u2022\u2022 Walking out.\\n\u2022\u2022 Using a loud, quarrelsome, or sarcastic voice.\\n\u2022\u2022 Using obscenities or swearing.\\n\u2022\u2022 Criticizing or complaining.\\n\u2022\u2022 Clenching your hands or fists.\\n\u2022\u2022 Frowning, not smiling, mean expression.\\n\u2022\u2022 Brooding or withdrawing from others.\\n\u2022\u2022 Crying.\\n\u2022\u2022 Grinning.\\n\u2022\u2022 A red or flushed face.\\n\u2022\u2022 Other:\\nAftereffects of Anger\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Attending only to the situation that\u2019s making\\nyou angry.\\n\u2022\u2022 Ruminating about the situation making you\\nangry or about situations in the past.\\n\u2022\u2022 Imagining future situations that will make you\\nangry.\\n\u2022\u2022 Depersonalization, dissociative experiences,\\nnumbness.\\n\u2022\u2022 Other:\\n(continued on next page)\\nNote. Adapted from Table 3 in Shaver, P., Schwartz, J., Kirson, D., & O\u2019Connor, C. (1987). Emotion knowledge: Further exploration of a proto-\\ntype approach. Journal of Personality and Social Psychology, 52(6), 1061\u20131086. Copyright 1987 by the American Psychological Association.\\nAdapted by permission.\"},{\"pdf_page\":239,\"book_page\":\"215\",\"text\":\"215\\nEmotion Regulation Handout 6   (p. 2 of 10)\\nDisgust Words\\ndisgust\\naversion\\ndislike\\ndistaste\\nrepugnance\\nresentment\\nsickened\\nabhorrence\\ncondescension\\nderision\\nhate\\nrepelled\\nrevolted\\nspite\\nantipathy\\ncontempt\\ndisdain\\nloathing\\nrepulsion\\nscorn\\nvile\\nPrompting Events for Feeling Disgust\\n\u2022\u2022 Seeing/smelling human or animal waste\\nproducts.\\n\u2022\u2022 Having a person or an animal that is dirty,\\nslimy, or unclean come close to you.\\n\u2022\u2022 Tasting something or being forced to swallow\\nsomething you really don\u2019t want.\\n\u2022\u2022 Seeing or being near a dead body.\\n\u2022\u2022 Touching items worn or owned by a stranger,\\ndead person, or disliked person.\\n\u2022\u2022 Observing or hearing about a person who\\ngrovels or who strips another person of\\ndignity.\\n\u2022\u2022 Seeing blood; getting blood drawn.\\n\u2022\u2022 Observing or hearing about a person acting\\nwith extreme hypocrisy/fawning.\\n\u2022\u2022 Observing or hearing about betrayal, child\\nabuse, racism, or other types of cruelty.\\n\u2022\u2022 Being forced to watch something that deeply\\nviolates your own Wise Mind values.\\n\u2022\u2022 Being confronted with someone who is\\ndeeply violating your own Wise Mind values.\\n\u2022\u2022 Being forced to engage in or watch unwanted\\nsexual contact.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Disgust\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You are swallowing something toxic.\\n\u2022\u2022 Your skin or your mind is being\\ncontaminated.\\n\u2022\u2022 Your own body or body parts are ugly.\\n\u2022\u2022 Others are evil or the \u201cscum\u201d of the earth,\\nor that they disrespect authority or the\\ngroup.\\n\u2022\u2022 Disapproving of/feeling morally superior to\\nanother.\\n\u2022\u2022 Extreme disapproval of yourself or your own\\nfeelings, thoughts, or behaviors.\\n\u2022\u2022 Judging that a person is deeply immoral or\\nhas sinned or violated the natural order of\\nthings.\\n\u2022\u2022 Judging someone\u2019s body as extremely ugly.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Disgust\\n\u2022\u2022 Feelings of nausea; sick feeling.\\n\u2022\u2022 Urge to vomit, vomiting, gagging, choking.\\n\u2022\u2022 Having a lump in your throat.\\n\u2022\u2022 Aversion to drinking or eating.\\n\u2022\u2022 Intense urge to destroy or get rid of\\nsomething.\\n\u2022\u2022 Urge to take a shower.\\n\u2022\u2022 Urge to run away or push away.\\n\u2022\u2022 Feeling contaminated, dirty, unclean.\\n\u2022\u2022 Feeling mentally polluted.\\n\u2022\u2022 Fainting.\\n\u2022\u2022 Other:\\nExpressions and Actions of Disgust\\n\u2022\u2022 Vomiting, spitting out.\\n\u2022\u2022 Closing your eyes, looking away.\\n\u2022\u2022 Washing, scrubbing, taking a bath.\\n\u2022\u2022 Changing your clothes; cleaning spaces.\\n\u2022\u2022 Avoiding eating or drinking.\\n\u2022\u2022 Pushing or kicking away; running away.\\n\u2022\u2022 Treating with disdain or disrespect.\\n\u2022\u2022 Stepping over; crowding another person out.\\n\u2022\u2022 Physically attacking causes of your disgust.\\n\u2022\u2022 Using obscenities or cursing.\\n\u2022\u2022 Clenching your hands or fists.\\n\u2022\u2022 Frowning, or not smiling.\\n\u2022\u2022 Mean or unpleasant facial expression.\\n\u2022\u2022 Speaking with a sarcastic voice tone.\\n\u2022\u2022 Nose and top lip tightened up; smirking.\\n\u2022\u2022 Other:\\nAftereffects of Disgust\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Ruminating about the situation that\u2019s making\\nyou feel disgusted.\\n\u2022\u2022 Becoming hypersensitive to dirt.\\n\u2022\u2022 Other:\\n(continued on next page)\"},{\"pdf_page\":240,\"book_page\":\"216\",\"text\":\"216\\nEmotion Regulation Handout 6   (p. 3 of 10)\\nEnvy Words\\nenvy\\ncraving\\ndispleased\\ngreed\\npettiness\\nbitterness\\ndiscontented\\ndissatisfied\\n\u201cgreen-eyed\u201d\\nresentment\\ncovetous\\ndisgruntled\\ndown-hearted\\nlonging\\nwishful\\nPrompting Events for Feeling Envy\\n\u2022\u2022 Someone has something you really want or\\nneed but don\u2019t or can\u2019t have.\\n\u2022\u2022 You are not part of the \u201cin\u201d crowd.\\n\u2022\u2022 Someone appears to have everything.\\n\u2022\u2022 You are alone while others are having fun.\\n\u2022\u2022 Someone else gets credit for what you\u2019ve\\ndone.\\n\u2022\u2022 Someone gets positive recognition for\\nsomething and you don\u2019t.\\n\u2022\u2022 Others get something you really want and\\nyou don\u2019t get it.\\n\u2022\u2022 Being around people who have more than\\nyou have.\\n\u2022\u2022 Someone you are competing with is more\\nsuccessful than you in an area important to\\nyou.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Envy\\n\u2022\u2022 Thinking you deserve what others have.\\n\u2022\u2022 Thinking others have more than you.\\n\u2022\u2022 Thinking about how unfair it is that you have\\nsuch a bad lot in life compared to others.\\n\u2022\u2022 Thinking you have been treated unfairly by\\nlife.\\n\u2022\u2022 Thinking you are unlucky.\\n\u2022\u2022 Thinking you are inferior, a failure, or\\nmediocre in comparison to others whom you\\nwant to be like.\\n\u2022\u2022 Comparing yourself to others who have more\\nthan you.\\n\u2022\u2022 Comparing yourself to people who have\\ncharacteristics that you wish you had.\\n\u2022\u2022 Thinking you are unappreciated.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Envy\\n\u2022\u2022 Muscles tightening.\\n\u2022\u2022 Teeth clamping together, mouth tightening.\\n\u2022\u2022 Feeling your face flush or get hot.\\n\u2022\u2022 Feeling rigidity in your body.\\n\u2022\u2022 Pain in the pit of the stomach.\\n\u2022\u2022 Having an urge to get even.\\n\u2022\u2022 Hating the other person.\\n\u2022\u2022 Wanting to hurt the people you envy.\\n\u2022\u2022 Wanting the person or people you envy to\\nlose what they have, to have bad luck, or to\\nbe hurt.\\n\u2022\u2022 Feeling pleasure when others experience\\nfailure or lose what they have.\\n\u2022\u2022 Feeling unhappy if another person\\nexperiences some good luck.\\n\u2022\u2022 Feeling motivated to improve yourself.\\n\u2022\u2022 Other:\\nExpressions and Actions of Envy\\n\u2022\u2022 Doing everything you can to get what the\\nother person has.\\n\u2022\u2022 Working a lot harder than you were to get\\nwhat you want.\\n\u2022\u2022 Trying to improve yourself and your situation.\\n\u2022\u2022 Taking away or ruining what the other person\\nhas.\\n\u2022\u2022 Attacking or criticizing the other person.\\n\u2022\u2022 Doing something to get even.\\n\u2022\u2022 Doing something to make the other person\\nfail or lose what he or she has.\\n\u2022\u2022 Saying mean things about the other person\\nor making the person look bad to others.\\n\u2022\u2022 Trying to show the other person up, to look\\nbetter than the other person.\\n\u2022\u2022 Avoiding persons who have what you want.\\n\u2022\u2022 Other:\\nAftereffects of Envy\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Attending only to what others have that you\\ndon\u2019t.\\n\u2022\u2022 Ruminating when others have had more than\\nyou.\\n\u2022\u2022 Discounting what you do have; not\\nappreciating things you have or things others\\ndo for you.\\n\u2022\u2022 Ruminating about what you don\u2019t have.\\n\u2022\u2022 Making resolutions to change.\\n\u2022\u2022 Other:\\n\\n(continued on next page)\"},{\"pdf_page\":241,\"book_page\":\"217\",\"text\":\"217\\nEmotion Regulation Handout 6   (p. 4 of 10)\\nFear Words\\nfear\\ndread\\nhorror\\nnervousness\\nshock\\nuneasiness\\nanxiety\\nedginess\\nhysteria\\noverwhelmed\\ntenseness\\nworry\\napprehension\\nfright\\njumpiness\\npanic\\nterror\\nPrompting Events for Feeling Fear\\n\u2022\u2022 Having your life, your health, or your well-\\nbeing threatened.\\n\u2022\u2022 Being in the same situation (or a similar one)\\nwhere you have been threatened or gotten\\nhurt in the past, or where painful things have\\nhappened.\\n\u2022\u2022 Flashbacks.\\n\u2022\u2022 Being in situations where you have seen\\nothers threatened or be hurt.\\n\u2022\u2022 Silence.\\n\u2022\u2022 Being in a new or unfamiliar situation.\\n\u2022\u2022 Being alone (e.g., walking alone, being home\\nalone, living alone).\\n\u2022\u2022 Being in the dark.\\n\u2022\u2022 Being in crowds.\\n\u2022\u2022 Leaving your home.\\n\u2022\u2022 Having to perform in front of others.\\n\u2022\u2022 Pursuing your dreams.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Fear\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You might die, or you are going to die.\\n\u2022\u2022 You might be hurt or harmed.\\n\u2022\u2022 You might lose something valuable.\\n\u2022\u2022 Someone might reject, criticize, or dislike\\nyou.\\n\u2022\u2022 You will embarrass yourself.\\n\u2022\u2022 Failure is possible; expecting to fail.\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You will not get help you want or need.\\n\u2022\u2022 You might lose help you already have.\\n\u2022\u2022 You might lose someone important.\\n\u2022\u2022 You might lose something you want.\\n\u2022\u2022 You are helpless or are losing a sense of\\ncontrol.\\n\u2022\u2022 You are incompetent or are losing mastery.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Fear\\n\u2022\u2022 Breathlessness.\\n\u2022\u2022 Fast heartbeat.\\n\u2022\u2022 Choking sensation, lump in throat.\\n\u2022\u2022 Muscles tensing, cramping.\\n\u2022\u2022 Clenching teeth.\\n\u2022\u2022 Urge to scream or call out.\\n\u2022\u2022 Feeling nauseated.\\n\u2022\u2022 Getting cold; feeling clammy.\\n\u2022\u2022 Feeling your hairs standing on end.\\n\u2022\u2022 Feeling of \u201cbutterflies\u201d in stomach.\\n\u2022\u2022 Wanting to run away or avoid things.\\n\u2022\u2022 Other:\\nExpressions and Actions of Fear\\n\u2022\u2022 Fleeing, running away.\\n\u2022\u2022 Running or walking hurriedly.\\n\u2022\u2022 Hiding from or avoiding what you fear.\\n\u2022\u2022 Engaging in nervous, fearful talk.\\n\u2022\u2022 Pleading or crying for help.\\n\u2022\u2022 Talking less or becoming speechless.\\n\u2022\u2022 Screaming or yelling.\\n\u2022\u2022 Darting eyes or quickly looking around.\\n\u2022\u2022 Frozen stare.\\n\u2022\u2022 Talking yourself out of doing what you fear.\\n\u2022\u2022 Freezing, or trying not to move.\\n\u2022\u2022 Crying or whimpering.\\n\u2022\u2022 Shaking, quivering, or trembling.\\n\u2022\u2022 A shaky or trembling voice.\\n\u2022\u2022 Sweating or perspiring.\\n\u2022\u2022 Diarrhea, vomiting.\\n\u2022\u2022 Hair erect.\\n\u2022\u2022 Other:\\nAftereffects of Fear\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Being hypervigilant to threat.\\n\u2022\u2022 Losing your ability to focus or becoming\\ndisoriented or dazed.\\n\u2022\u2022 Losing control.\\n\u2022\u2022 Imagining the possibility of more loss or\\nfailure.\\n\u2022\u2022 Isolating yourself.\\n\u2022\u2022 Ruminating about other threatening times.\\n\u2022\u2022 Other:\\n(continued on next page)\"},{\"pdf_page\":242,\"book_page\":\"218\",\"text\":\"218\\nEmotion Regulation Handout 6   (p. 5 of 10)\\nHappiness Words\\nhappiness\\nsatisfaction\\njoviality\\nexhilaration\\necstasy\\njoy\\nbliss\\ntriumph\\noptimism\\ngladness\\nenjoyment\\nenthusiasm\\ncontentment\\nzest\\npride\\nrelief\\njolliness\\nexcitement\\neagerness\\nelation\\namusement\\nthrill\\njubilation\\ngaiety\\nglee\\nenthrallment\\ncheerfulness\\nzaniness\\npleasure\\nrapture\\nhope\\neuphoria\\ndelight\\nzeal\\nPrompting Events for Feeling Happiness\\n\u2022\u2022 Receiving a wonderful surprise.\\n\u2022\u2022 Reality exceeding your expectations.\\n\u2022\u2022 Getting what you want.\\n\u2022\u2022 Getting something you have worked hard for\\nor worried about.\\n\u2022\u2022 Things turning out better than you thought\\nthey would.\\n\u2022\u2022 Being successful at a task.\\n\u2022\u2022 Achieving a desirable outcome.\\n\u2022\u2022 Receiving esteem, respect, or praise.\\n\u2022\u2022 Receiving love, liking, or affection.\\n\u2022\u2022 Being accepted by others.\\n\u2022\u2022 Belonging somewhere or with someone or a\\ngroup.\\n\u2022\u2022 Being with or in contact with people who love\\nor like you.\\n\u2022\u2022 Having very pleasurable sensations.\\n\u2022\u2022 Doing things that create or bring to mind\\npleasurable sensations.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Happiness\\n\u2022\u2022 Interpreting joyful events just as they are, without adding or subtracting.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Happiness\\n\u2022\u2022 Feeling excited.\\n\u2022\u2022 Feeling physically energetic, active.\\n\u2022\u2022 Feeling like giggling or laughing.\\n\u2022\u2022 Feeling your face flush.\\n\u2022\u2022 Feeling calm all the way through.\\n\u2022\u2022 Urge to keep doing what is associated with\\nhappiness.\\n\u2022\u2022 Feeling at peace.\\n\u2022\u2022 Feeling open or expansive.\\n\u2022\u2022 Other:\\nExpressions and Actions of Happiness\\n\u2022\u2022 Smiling.\\n\u2022\u2022 Having a bright, glowing face.\\n\u2022\u2022 Being bouncy or bubbly.\\n\u2022\u2022 Communicating your good feelings.\\n\u2022\u2022 Sharing the feeling.\\n\u2022\u2022 Silliness.\\n\u2022\u2022 Hugging people.\\n\u2022\u2022 Jumping up and down.\\n\u2022\u2022 Saying positive things.\\n\u2022\u2022 Using an enthusiastic or excited voice.\\n\u2022\u2022 Being talkative or talking a lot.\\n\u2022\u2022 Other:\\nAftereffects of Happiness\\n\u2022\u2022 Being courteous or friendly to others.\\n\u2022\u2022 Doing nice things for other people.\\n\u2022\u2022 Having a positive outlook; seeing the bright\\nside.\\n\u2022\u2022 Having a high threshold for worry or\\nannoyance.\\n\u2022\u2022 Remembering and imagining other times you\\nhave felt joyful.\\n\u2022\u2022 Expecting to feel joyful in the future.\\n\u2022\u2022 Other:\\n\\n(continued on next page)\"},{\"pdf_page\":243,\"book_page\":\"219\",\"text\":\"219\\nEmotion Regulation Handout 6   (p. 6 of 10)\\nJealousy Words\\njealous\\nclutching\\nfear of losing someone/\\nsomething\\nrivalrous\\nwary\\ncautious\\ndefensive\\nsuspicious\\nwatchful\\nclinging\\nmistrustful\\npossessive\\nself-protective\\nPrompting Events for Feeling Jealous\\n\u2022\u2022 An important relationship is threatened or in\\ndanger of being lost.\\n\u2022\u2022 A potential competitor pays attention to\\nsomeone you love.\\n\u2022\u2022 Someone:\\n\u2022\u2022 Is threatening to take away important things\\nin your life.\\n\u2022\u2022 Goes out with the person you like.\\n\u2022\u2022 Ignores you while talking to a friend of\\nyours.\\n\u2022\u2022 Is more attractive, outgoing, or self-\\nconfident than you.\\n\u2022\u2022 You are treated as unimportant by a person\\nyou want to be close to.\\n\u2022\u2022 Your partner tells you that he or she desires\\nmore time alone.\\n\u2022\u2022 Your partner appears to flirt with someone\\nelse.\\n\u2022\u2022 A person you are romantically involved with\\nlooks at someone else.\\n\u2022\u2022 You find the person you love is having an\\naffair with someone else.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Jealousy\\n\u2022\u2022 Believing that:\\n\u2022\u2022 Your partner does not care for you any\\nmore.\\n\u2022\u2022 You are nothing to your partner.\\n\u2022\u2022 Your partner is going to leave you.\\n\u2022\u2022 Your partner is behaving inappropriately.\\n\u2022\u2022 You don\u2019t measure up to your peers.\\n\u2022\u2022 I deserve more than what you are receiving.\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You were cheated.\\n\u2022\u2022 No one cares about you.\\n\u2022\u2022 Your rival is possessive and competitive.\\n\u2022\u2022 Your rival is insecure.\\n\u2022\u2022 Your rival is envious.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Jealousy\\n\u2022\u2022 Breathlessness.\\n\u2022\u2022 Fast heartbeat.\\n\u2022\u2022 Choking sensation, lump in throat.\\n\u2022\u2022 Muscles tensing.\\n\u2022\u2022 Teeth clenching.\\n\u2022\u2022 Becoming suspicious of others.\\n\u2022\u2022 Having injured pride.\\n\u2022\u2022 Feelings of rejection.\\n\u2022\u2022 Needing to be in control.\\n\u2022\u2022 Feeling helpless.\\n\u2022\u2022 Wanting to grasp or keep hold of what you\\nhave.\\n\u2022\u2022 Wanting to push away or eliminate your rival.\\nExpressions and Actions of Jealousy\\n\u2022\u2022 Violent behavior or threats of violence toward\\nthe person threatening to take something\\naway.\\n\u2022\u2022 Attempting to control the freedom of the\\nperson you are afraid of losing.\\n\u2022\u2022 Verbal accusations of disloyalty or\\nunfaithfulness.\\n\u2022\u2022 Spying on the person.\\n\u2022\u2022 Interrogating the person; demanding\\naccounting of time or activities.\\n\u2022\u2022 Collecting evidence of wrongdoings.\\n\u2022\u2022 Clinging; enhanced dependency.\\n\u2022\u2022 Increased or excessive demonstrations of\\nlove.\\n\u2022\u2022 Other:\\nAftereffects of Jealousy\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Seeing the worst in others.\\n\u2022\u2022 Being mistrustful across the board.\\n\u2022\u2022 Being hypervigilant to threats to your\\nrelationships.\\n\u2022\u2022 Becoming isolated or withdrawn.\\n\u2022\u2022 Other:\\n\\n(continued on next page)\"},{\"pdf_page\":244,\"book_page\":\"220\",\"text\":\"220\\nEmotion Regulation Handout 6   (p. 7 of 10)\\nLove Words\\nlove\\nattraction\\nenchantment\\nlimerence\\nsympathy\\nadoration\\ncaring\\nfondness\\nlonging\\ntenderness\\naffection\\ncharmed\\ninfatuation\\nlust\\nwarmth\\narousal\\ncompassion\\nkindness\\npassion\\ndesire\\nliking\\nsentimentality\\nPrompting Events for Feeling Love\\n\u2022\u2022 A person:\\n\u2022\u2022 Offers or gives you something you want,\\nneed, or desire.\\n\u2022\u2022 Does things you want or need.\\n\u2022\u2022 Does things you particularly value or\\nadmire.\\n\u2022\u2022 Feeling physically attracted to someone.\\n\u2022\u2022 Being with someone you have fun with.\\n\u2022\u2022 You spend a lot of time with a person.\\n\u2022\u2022 You share a special experience with a\\nperson.\\n\u2022\u2022 You have exceptionally good communication\\nwith a person.\\n\u2022\u2022 Other:\\n\\nInterpretations of Events That Prompt Feelings of Love\\n\u2022\u2022 Believing that a person loves, needs, or appreciates you.\\n\u2022\u2022 Thinking that a person is physically attractive.\\n\u2022\u2022 Judging a person\u2019s personality as wonderful, pleasing, or attractive.\\n\u2022\u2022 Believing that a person can be counted on, or will always be there for you.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Love\\n\u2022\u2022 When you are with or thinking about\\nsomeone:\\n\u2022\u2022 Feeling excited and full of energy.\\n\u2022\u2022 Fast heartbeat.\\n\u2022\u2022 Feeling self-confident.\\n\u2022\u2022 Feeling invulnerable.\\n\u2022\u2022 Feeling happy, joyful, or exuberant.\\n\u2022\u2022 Feeling warm, trusting, and secure.\\n\u2022\u2022 Feeling relaxed and calm.\\n\u2022\u2022 Wanting the best for a person.\\n\u2022\u2022 Wanting to give things to a person.\\n\u2022\u2022 Wanting to see and spend time with a person.\\n\u2022\u2022 Wanting to spend your life with a person.\\n\u2022\u2022 Wanting physical closeness or sex.\\n\u2022\u2022 Wanting emotional closeness.\\n\\nExpressions and Actions of Love\\n\u2022\u2022 Saying \u201cI love you.\u201d\\n\u2022\u2022 Expressing positive feelings to a person.\\n\u2022\u2022 Eye contact, mutual gaze.\\n\u2022\u2022 Touching, petting, hugging, holding, cuddling.\\n\u2022\u2022 Sexual activity.\\n\u2022\u2022 Smiling.\\n\u2022\u2022 Sharing time and experiences with someone.\\n\u2022\u2022 Doing things that the other person wants or\\nneeds.\\n\u2022\u2022 Other:\\nAftereffects of Love\\n\u2022\u2022 Only seeing a person\u2019s positive side.\\n\u2022\u2022 Feeling forgetful or distracted; daydreaming.\\n\u2022\u2022 Feeling openness and trust.\\n\u2022\u2022 Feeling \u201calive,\u201d capable.\\n\u2022\u2022 Remembering other people you have loved.\\n\u2022\u2022 Remembering other people who have loved\\nyou.\\n\u2022\u2022 Remembering other positive events.\\n\u2022\u2022 Believing in yourself; believing you are\\nwonderful, capable, competent.\\n\u2022\u2022 Other:\\n(continued on next page)\"},{\"pdf_page\":245,\"book_page\":\"221\",\"text\":\"221\\nEmotion Regulation Handout 6   (p. 8 of 10)\\nSadness Words\\nsadness\\ndisappointment\\npity\\ncrushed\\ndisconnected\\ndepression\\ndespair\\nhomesickness\\nanguish\\ndispleasure\\nsuffering\\nglumness\\ngrief\\nneglect\\ndismay\\ninsecurity\\ndejection\\nmelancholy\\nmisery\\nalienation\\nhurt\\nsorrow\\ngloom\\nalone\\nagony\\ndiscontentment\\nrejection\\ndefeat\\nloneliness\\nwoe\\ndi\\u0007straught\\nunhappiness\\nPrompting Events for Feeling Sadness\\n\u2022\u2022 Losing something or someone irretrievably.\\n\u2022\u2022 The death of someone you love.\\n\u2022\u2022 Things not being what you expected or\\nwanted.\\n\u2022\u2022 Things being worse than you expected.\\n\u2022\u2022 Being separated from someone you care for.\\n\u2022\u2022 Getting what you don\u2019t want.\\n\u2022\u2022 Not getting what you have worked for.\\n\u2022\u2022 Not getting what you believe you need in life.\\n\u2022\u2022 Being rejected, disapproved of, or excluded.\\n\u2022\u2022 Discovering that you are powerless or\\nhelpless.\\n\u2022\u2022 Being with someone else who is sad or in\\npain.\\n\u2022\u2022 Reading or hearing about other people\u2019s\\nproblems or troubles in the world.\\n\u2022\u2022 Being alone, or feeling isolated or like an\\noutsider.\\n\u2022\u2022 Thinking about everything you have not\\ngotten.\\n\u2022\u2022 Thinking about your losses.\\n\u2022\u2022 Thinking about missing someone.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Sadness\\n\u2022\u2022 Believing that a separation from someone will\\nlast for a long time or will never end.\\n\u2022\u2022 Believing that you will not get what you want\\nor need in your life.\\n\u2022\u2022 Seeing things or your life as hopeless.\\n\u2022\u2022 Believing that you are worthless or not\\nvaluable.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Sadness\\n\u2022\u2022 Feeling tired, run down, or low in energy.\\n\u2022\u2022 Feeling lethargic, listless; wanting to stay in\\nbed all day.\\n\u2022\u2022 Feeling as if nothing is pleasurable any more.\\n\u2022\u2022 Pain or hollowness in your chest or gut.\\n\u2022\u2022 Feeling empty.\\n\u2022\u2022 Feeling as if you can\u2019t stop crying, or if you\\never start crying you will never be able to\\nstop.\\n\u2022\u2022 Difficulty swallowing.\\n\u2022\u2022 Breathlessness.\\n\u2022\u2022 Dizziness.\\n\u2022\u2022 Other:\\nExpressions and Actions of Sadness\\n\u2022\u2022 Avoiding things.\\n\u2022\u2022 Acting helpless; staying in bed; being\\ninactive.\\n\u2022\u2022 Moping, brooding, or acting moody.\\n\u2022\u2022 Making slow, shuffling movements.\\n\u2022\u2022 Withdrawing from social contact.\\n\u2022\u2022 Avoiding activities that used to bring pleasure.\\n\u2022\u2022 Giving up and no longer trying to improve.\\n\u2022\u2022 Saying sad things.\\n\u2022\u2022 Talking little or not at all.\\n\u2022\u2022 Using a quiet, slow, or monotonous voice.\\n\u2022\u2022 Eyes drooping.\\n\u2022\u2022 Frowning, not smiling.\\n\u2022\u2022 Posture slumping.\\n\u2022\u2022 Sobbing, crying, whimpering.\\n\u2022\u2022 Other:\\nAftereffects of Sadness\\n\u2022\u2022 Not being able to remember happy things.\\n\u2022\u2022 Feeling irritable, touchy, or grouchy.\\n\u2022\u2022 Yearning and searching for the thing lost.\\n\u2022\u2022 Having a negative outlook.\\n\u2022\u2022 Blaming or criticizing yourself.\\n\u2022\u2022 Ruminating about sad events in the past.\\n\u2022\u2022 Insomnia.\\n\u2022\u2022 Appetite disturbance, indigestion.\\n\u2022\u2022 Other:\\n\\n(continued on next page)\"},{\"pdf_page\":246,\"book_page\":\"222\",\"text\":\"222\\nEmotion Regulation Handout 6   (p. 9 of 10)\\nShame Words\\nshame\\nculpability\\nembarrassment\\nmortification\\nshyness\\ncontrition\\ndiscomposure\\nhumiliation\\nself-conscious\\nPrompting Events for Feeling Shame\\n\u2022\u2022 Being rejected by people you care about.\\n\u2022\u2022 Having others find out that you have done\\nsomething wrong.\\n\u2022\u2022 Doing (or feeling or thinking) something\\nthat people you admire believe is wrong or\\nimmoral.\\n\u2022\u2022 Comparing some aspect of yourself or your\\nbehavior to a standard and feeling as if you\\ndo not live up to that standard.\\n\u2022\u2022 Being betrayed by a person you love.\\n\u2022\u2022 Being laughed at/made fun of.\\n\u2022\u2022 Being criticized in public/in front of someone\\nelse; remembering public criticism.\\n\u2022\u2022 Others attacking your integrity.\\n\u2022\u2022 Being reminded of something wrong,\\nimmoral, or \u201cshameful\u201d you did in the past.\\n\u2022\u2022 Being rejected or criticized for something you\\nexpected praise for.\\n\u2022\u2022 Having emotions/experiences that have been\\ninvalidated.\\n\u2022\u2022 Exposure of a very private aspect of yourself\\nor your life.\\n\u2022\u2022 Exposure of a physical characteristic you\\ndislike.\\n\u2022\u2022 Failing at something you feel you are (or\\nshould be) competent to do.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Shame\\n\u2022\u2022 Believing that others will reject you (or have\\nrejected you).\\n\u2022\u2022 Judging yourself to be inferior, not \u201cgood\\nenough,\u201d not as good as others; self-\\ninvalidation.\\n\u2022\u2022 Comparing yourself to others and thinking\\nthat you are a \u201closer.\u201d\\n\u2022\u2022 Believing yourself unlovable.\\n\u2022\u2022 Thinking that you are bad, immoral, or wrong.\\n\u2022\u2022 Thinking that you are defective.\\n\u2022\u2022 Thinking that you are a bad person or a\\nfailure.\\n\u2022\u2022 Believing your body (or a body part) is too\\nbig, too small, or ugly.\\n\u2022\u2022 Thinking that you have not lived up to others\u2019\\nexpectations of you.\\n\u2022\u2022 Thinking that your behavior, thoughts, or\\nfeelings are silly or stupid.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Shame\\n\u2022\u2022 Pain in the pit of the stomach.\\n\u2022\u2022 Sense of dread.\\n\u2022\u2022 Wanting to shrink down and/or disappear.\\n\u2022\u2022 Wanting to hide or cover your face and body.\\n\u2022\u2022 Other:\\nExpressions and Actions of Shame\\n\u2022\u2022 Hiding behavior or a characteristic from other\\npeople.\\n\u2022\u2022 Avoiding the person you have harmed.\\n\u2022\u2022 Avoiding persons who have criticized you.\\n\u2022\u2022 Avoiding yourself\u2014distracting, ignoring.\\n\u2022\u2022 Withdrawing; covering the face.\\n\u2022\u2022 Bowing your head, groveling.\\n\u2022\u2022 Appeasing; saying you are sorry over and\\nover and over.\\n\u2022\u2022 Looking down and away from others.\\n\u2022\u2022 Sinking back; slumped and rigid posture.\\n\u2022\u2022 Halting speech; lowered volume while talking.\\n\u2022\u2022 Other:\\nAftereffects of Shame\\n\u2022\u2022 Avoiding thinking about your transgression;\\nshutting down; blocking all emotions.\\n\u2022\u2022 Engaging in distracting, impulsive behaviors\\nto divert your mind or attention.\\n\u2022\u2022 High amount of \u201cself-focus\u201d; preoccupation\\nwith yourself.\\n\u2022\u2022 Depersonalization, dissociative experiences,\\nnumbness, or shock.\\n\u2022\u2022 Attacking or blaming others.\\n\u2022\u2022 Conflicts with other people.\\n\u2022\u2022 Isolation, feeling alienated.\\n\u2022\u2022 Impairment in problem-solving ability.\\n\u2022\u2022 Other:\\n\\n(continued on next page)\"},{\"pdf_page\":238,\"book_page\":\"214\",\"text\":\"214\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\n\u2610\\nEmotion Regulation Handout 6 (Emotion Regulation Worksheets 4, 4a) (p. 1 of 10)\\nWays to Describe Emotions\\nAnger Words\\nanger\\nbitterness\\nfury\\nindignation\\nvengefulness\\naggravation\\nexasperation\\ngrouchiness\\nirritation\\nwrath\\nagitation\\nferocity\\ngrumpiness\\noutrage\\nannoyance\\nfrustration\\nhostility\\nrage\\nPrompting Events for Feeling Anger\\n\u2022\u2022 Having an important goal blocked.\\n\u2022\u2022 You or someone you care about being\\nattacked or threatened by others.\\n\u2022\u2022 Losing power, status, or respect.\\n\u2022\u2022 Not having things turn out as expected.\\n\u2022\u2022 Physical or emotional pain.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Anger\\n\u2022\u2022 Believing that you have been treated unfairly.\\n\u2022\u2022 Blaming.\\n\u2022\u2022 Believing that important goals are being\\nblocked or stopped.\\n\u2022\u2022 Believing that things \u201cshould\u201d be different\\nthan they are.\\n\u2022\u2022 Rigidly thinking, \u201cI\u2019m right.\u201d\\n\u2022\u2022 Judging that the situation is illegitimate or\\nwrong.\\n\u2022\u2022 Ruminating about the event that set off the\\nanger in the first place.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Anger\\n\u2022\u2022 Muscles tightening.\\n\u2022\u2022 Teeth clamping together.\\n\u2022\u2022 Hands clenching.\\n\u2022\u2022 Feeling your face flush or get hot.\\n\u2022\u2022 Feeling like you are going to explode.\\n\u2022\u2022 Being unable to stop tears.\\n\u2022\u2022 Wanting to hit someone, bang the wall, throw\\nsomething, blow up.\\n\u2022\u2022 Wanting to hurt someone.\\n\u2022\u2022 Other:\\nExpressions and Actions of Anger\\n\u2022\u2022 Physically or verbally attacking.\\n\u2022\u2022 Making aggressive or threatening gestures.\\n\u2022\u2022 Pounding, throwing things, breaking things.\\n\u2022\u2022 Walking heavily, stomping, slamming doors.\\n\u2022\u2022 Walking out.\\n\u2022\u2022 Using a loud, quarrelsome, or sarcastic voice.\\n\u2022\u2022 Using obscenities or swearing.\\n\u2022\u2022 Criticizing or complaining.\\n\u2022\u2022 Clenching your hands or fists.\\n\u2022\u2022 Frowning, not smiling, mean expression.\\n\u2022\u2022 Brooding or withdrawing from others.\\n\u2022\u2022 Crying.\\n\u2022\u2022 Grinning.\\n\u2022\u2022 A red or flushed face.\\n\u2022\u2022 Other:\\nAftereffects of Anger\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Attending only to the situation that\u2019s making\\nyou angry.\\n\u2022\u2022 Ruminating about the situation making you\\nangry or about situations in the past.\\n\u2022\u2022 Imagining future situations that will make you\\nangry.\\n\u2022\u2022 Depersonalization, dissociative experiences,\\nnumbness.\\n\u2022\u2022 Other:\\n(continued on next page)\\nNote. Adapted from Table 3 in Shaver, P., Schwartz, J., Kirson, D., & O\u2019Connor, C. (1987). Emotion knowledge: Further exploration of a proto-\\ntype approach. Journal of Personality and Social Psychology, 52(6), 1061\u20131086. Copyright 1987 by the American Psychological Association.\\nAdapted by permission.\"},{\"pdf_page\":239,\"book_page\":\"215\",\"text\":\"215\\nEmotion Regulation Handout 6 (p. 2 of 10)\\nDisgust Words\\ndisgust\\naversion\\ndislike\\ndistaste\\nrepugnance\\nresentment\\nsickened\\nabhorrence\\ncondescension\\nderision\\nhate\\nrepelled\\nrevolted\\nspite\\nantipathy\\ncontempt\\ndisdain\\nloathing\\nrepulsion\\nscorn\\nvile\\nPrompting Events for Feeling Disgust\\n\u2022\u2022 Seeing/smelling human or animal waste\\nproducts.\\n\u2022\u2022 Having a person or an animal that is dirty,\\nslimy, or unclean come close to you.\\n\u2022\u2022 Tasting something or being forced to swallow\\nsomething you really don\u2019t want.\\n\u2022\u2022 Seeing or being near a dead body.\\n\u2022\u2022 Touching items worn or owned by a stranger,\\ndead person, or disliked person.\\n\u2022\u2022 Observing or hearing about a person who\\ngrovels or who strips another person of\\ndignity.\\n\u2022\u2022 Seeing blood; getting blood drawn.\\n\u2022\u2022 Observing or hearing about a person acting\\nwith extreme hypocrisy/fawning.\\n\u2022\u2022 Observing or hearing about betrayal, child\\nabuse, racism, or other types of cruelty.\\n\u2022\u2022 Being forced to watch something that deeply\\nviolates your own Wise Mind values.\\n\u2022\u2022 Being confronted with someone who is\\ndeeply violating your own Wise Mind values.\\n\u2022\u2022 Being forced to engage in or watch unwanted\\nsexual contact.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Disgust\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You are swallowing something toxic.\\n\u2022\u2022 Your skin or your mind is being\\ncontaminated.\\n\u2022\u2022 Your own body or body parts are ugly.\\n\u2022\u2022 Others are evil or the \u201cscum\u201d of the earth,\\nor that they disrespect authority or the\\ngroup.\\n\u2022\u2022 Disapproving of/feeling morally superior to\\nanother.\\n\u2022\u2022 Extreme disapproval of yourself or your own\\nfeelings, thoughts, or behaviors.\\n\u2022\u2022 Judging that a person is deeply immoral or\\nhas sinned or violated the natural order of\\nthings.\\n\u2022\u2022 Judging someone\u2019s body as extremely ugly.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Disgust\\n\u2022\u2022 Feelings of nausea; sick feeling.\\n\u2022\u2022 Urge to vomit, vomiting, gagging, choking.\\n\u2022\u2022 Having a lump in your throat.\\n\u2022\u2022 Aversion to drinking or eating.\\n\u2022\u2022 Intense urge to destroy or get rid of\\nsomething.\\n\u2022\u2022 Urge to take a shower.\\n\u2022\u2022 Urge to run away or push away.\\n\u2022\u2022 Feeling contaminated, dirty, unclean.\\n\u2022\u2022 Feeling mentally polluted.\\n\u2022\u2022 Fainting.\\n\u2022\u2022 Other:\\nExpressions and Actions of Disgust\\n\u2022\u2022 Vomiting, spitting out.\\n\u2022\u2022 Closing your eyes, looking away.\\n\u2022\u2022 Washing, scrubbing, taking a bath.\\n\u2022\u2022 Changing your clothes; cleaning spaces.\\n\u2022\u2022 Avoiding eating or drinking.\\n\u2022\u2022 Pushing or kicking away; running away.\\n\u2022\u2022 Treating with disdain or disrespect.\\n\u2022\u2022 Stepping over; crowding another person out.\\n\u2022\u2022 Physically attacking causes of your disgust.\\n\u2022\u2022 Using obscenities or cursing.\\n\u2022\u2022 Clenching your hands or fists.\\n\u2022\u2022 Frowning, or not smiling.\\n\u2022\u2022 Mean or unpleasant facial expression.\\n\u2022\u2022 Speaking with a sarcastic voice tone.\\n\u2022\u2022 Nose and top lip tightened up; smirking.\\n\u2022\u2022 Other:\\nAftereffects of Disgust\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Ruminating about the situation that\u2019s making\\nyou feel disgusted.\\n\u2022\u2022 Becoming hypersensitive to dirt.\\n\u2022\u2022 Other:\\n(continued on next page)\"},{\"pdf_page\":240,\"book_page\":\"216\",\"text\":\"216\\nEmotion Regulation Handout 6 (p. 3 of 10)\\nEnvy Words\\nenvy\\ncraving\\ndispleased\\ngreed\\npettiness\\nbitterness\\ndiscontented\\ndissatisfied\\n\u201cgreen-eyed\u201d\\nresentment\\ncovetous\\ndisgruntled\\ndown-hearted\\nlonging\\nwishful\\nPrompting Events for Feeling Envy\\n\u2022\u2022 Someone has something you really want or\\nneed but don\u2019t or can\u2019t have.\\n\u2022\u2022 You are not part of the \u201cin\u201d crowd.\\n\u2022\u2022 Someone appears to have everything.\\n\u2022\u2022 You are alone while others are having fun.\\n\u2022\u2022 Someone else gets credit for what you\u2019ve\\ndone.\\n\u2022\u2022 Someone gets positive recognition for\\nsomething and you don\u2019t.\\n\u2022\u2022 Others get something you really want and\\nyou don\u2019t get it.\\n\u2022\u2022 Being around people who have more than\\nyou have.\\n\u2022\u2022 Someone you are competing with is more\\nsuccessful than you in an area important to\\nyou.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Envy\\n\u2022\u2022 Thinking you deserve what others have.\\n\u2022\u2022 Thinking others have more than you.\\n\u2022\u2022 Thinking about how unfair it is that you have\\nsuch a bad lot in life compared to others.\\n\u2022\u2022 Thinking you have been treated unfairly by\\nlife.\\n\u2022\u2022 Thinking you are unlucky.\\n\u2022\u2022 Thinking you are inferior, a failure, or\\nmediocre in comparison to others whom you\\nwant to be like.\\n\u2022\u2022 Comparing yourself to others who have more\\nthan you.\\n\u2022\u2022 Comparing yourself to people who have\\ncharacteristics that you wish you had.\\n\u2022\u2022 Thinking you are unappreciated.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Envy\\n\u2022\u2022 Muscles tightening.\\n\u2022\u2022 Teeth clamping together, mouth tightening.\\n\u2022\u2022 Feeling your face flush or get hot.\\n\u2022\u2022 Feeling rigidity in your body.\\n\u2022\u2022 Pain in the pit of the stomach.\\n\u2022\u2022 Having an urge to get even.\\n\u2022\u2022 Hating the other person.\\n\u2022\u2022 Wanting to hurt the people you envy.\\n\u2022\u2022 Wanting the person or people you envy to\\nlose what they have, to have bad luck, or to\\nbe hurt.\\n\u2022\u2022 Feeling pleasure when others experience\\nfailure or lose what they have.\\n\u2022\u2022 Feeling unhappy if another person\\nexperiences some good luck.\\n\u2022\u2022 Feeling motivated to improve yourself.\\n\u2022\u2022 Other:\\nExpressions and Actions of Envy\\n\u2022\u2022 Doing everything you can to get what the\\nother person has.\\n\u2022\u2022 Working a lot harder than you were to get\\nwhat you want.\\n\u2022\u2022 Trying to improve yourself and your situation.\\n\u2022\u2022 Taking away or ruining what the other person\\nhas.\\n\u2022\u2022 Attacking or criticizing the other person.\\n\u2022\u2022 Doing something to get even.\\n\u2022\u2022 Doing something to make the other person\\nfail or lose what he or she has.\\n\u2022\u2022 Saying mean things about the other person\\nor making the person look bad to others.\\n\u2022\u2022 Trying to show the other person up, to look\\nbetter than the other person.\\n\u2022\u2022 Avoiding persons who have what you want.\\n\u2022\u2022 Other:\\nAftereffects of Envy\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Attending only to what others have that you\\ndon\u2019t.\\n\u2022\u2022 Ruminating when others have had more than\\nyou.\\n\u2022\u2022 Discounting what you do have; not\\nappreciating things you have or things others\\ndo for you.\\n\u2022\u2022 Ruminating about what you don\u2019t have.\\n\u2022\u2022 Making resolutions to change.\\n\u2022\u2022 Other: (continued on next page)\"},{\"pdf_page\":241,\"book_page\":\"217\",\"text\":\"217\\nEmotion Regulation Handout 6 (p. 4 of 10)\\nFear Words\\nfear\\ndread\\nhorror\\nnervousness\\nshock\\nuneasiness\\nanxiety\\nedginess\\nhysteria\\noverwhelmed\\ntenseness\\nworry\\napprehension\\nfright\\njumpiness\\npanic\\nterror\\nPrompting Events for Feeling Fear\\n\u2022\u2022 Having your life, your health, or your well-\\nbeing threatened.\\n\u2022\u2022 Being in the same situation (or a similar one)\\nwhere you have been threatened or gotten\\nhurt in the past, or where painful things have\\nhappened.\\n\u2022\u2022 Flashbacks.\\n\u2022\u2022 Being in situations where you have seen\\nothers threatened or be hurt.\\n\u2022\u2022 Silence.\\n\u2022\u2022 Being in a new or unfamiliar situation.\\n\u2022\u2022 Being alone (e.g., walking alone, being home\\nalone, living alone).\\n\u2022\u2022 Being in the dark.\\n\u2022\u2022 Being in crowds.\\n\u2022\u2022 Leaving your home.\\n\u2022\u2022 Having to perform in front of others.\\n\u2022\u2022 Pursuing your dreams.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Fear\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You might die, or you are going to die.\\n\u2022\u2022 You might be hurt or harmed.\\n\u2022\u2022 You might lose something valuable.\\n\u2022\u2022 Someone might reject, criticize, or dislike\\nyou.\\n\u2022\u2022 You will embarrass yourself.\\n\u2022\u2022 Failure is possible; expecting to fail.\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You will not get help you want or need.\\n\u2022\u2022 You might lose help you already have.\\n\u2022\u2022 You might lose someone important.\\n\u2022\u2022 You might lose something you want.\\n\u2022\u2022 You are helpless or are losing a sense of\\ncontrol.\\n\u2022\u2022 You are incompetent or are losing mastery.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Fear\\n\u2022\u2022 Breathlessness.\\n\u2022\u2022 Fast heartbeat.\\n\u2022\u2022 Choking sensation, lump in throat.\\n\u2022\u2022 Muscles tensing, cramping.\\n\u2022\u2022 Clenching teeth.\\n\u2022\u2022 Urge to scream or call out.\\n\u2022\u2022 Feeling nauseated.\\n\u2022\u2022 Getting cold; feeling clammy.\\n\u2022\u2022 Feeling your hairs standing on end.\\n\u2022\u2022 Feeling of \u201cbutterflies\u201d in stomach.\\n\u2022\u2022 Wanting to run away or avoid things.\\n\u2022\u2022 Other:\\nExpressions and Actions of Fear\\n\u2022\u2022 Fleeing, running away.\\n\u2022\u2022 Running or walking hurriedly.\\n\u2022\u2022 Hiding from or avoiding what you fear.\\n\u2022\u2022 Engaging in nervous, fearful talk.\\n\u2022\u2022 Pleading or crying for help.\\n\u2022\u2022 Talking less or becoming speechless.\\n\u2022\u2022 Screaming or yelling.\\n\u2022\u2022 Darting eyes or quickly looking around.\\n\u2022\u2022 Frozen stare.\\n\u2022\u2022 Talking yourself out of doing what you fear.\\n\u2022\u2022 Freezing, or trying not to move.\\n\u2022\u2022 Crying or whimpering.\\n\u2022\u2022 Shaking, quivering, or trembling.\\n\u2022\u2022 A shaky or trembling voice.\\n\u2022\u2022 Sweating or perspiring.\\n\u2022\u2022 Diarrhea, vomiting.\\n\u2022\u2022 Hair erect.\\n\u2022\u2022 Other:\\nAftereffects of Fear\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Being hypervigilant to threat.\\n\u2022\u2022 Losing your ability to focus or becoming\\ndisoriented or dazed.\\n\u2022\u2022 Losing control.\\n\u2022\u2022 Imagining the possibility of more loss or\\nfailure.\\n\u2022\u2022 Isolating yourself.\\n\u2022\u2022 Ruminating about other threatening times.\\n\u2022\u2022 Other:\\n(continued on next page)\"},{\"pdf_page\":242,\"book_page\":\"218\",\"text\":\"218\\nEmotion Regulation Handout 6 (p. 5 of 10)\\nHappiness Words\\nhappiness\\nsatisfaction\\njoviality\\nexhilaration\\necstasy\\njoy\\nbliss\\ntriumph\\noptimism\\ngladness\\nenjoyment\\nenthusiasm\\ncontentment\\nzest\\npride\\nrelief\\njolliness\\nexcitement\\neagerness\\nelation\\namusement\\nthrill\\njubilation\\ngaiety\\nglee\\nenthrallment\\ncheerfulness\\nzaniness\\npleasure\\nrapture\\nhope\\neuphoria\\ndelight\\nzeal\\nPrompting Events for Feeling Happiness\\n\u2022\u2022 Receiving a wonderful surprise.\\n\u2022\u2022 Reality exceeding your expectations.\\n\u2022\u2022 Getting what you want.\\n\u2022\u2022 Getting something you have worked hard for\\nor worried about.\\n\u2022\u2022 Things turning out better than you thought\\nthey would.\\n\u2022\u2022 Being successful at a task.\\n\u2022\u2022 Achieving a desirable outcome.\\n\u2022\u2022 Receiving esteem, respect, or praise.\\n\u2022\u2022 Receiving love, liking, or affection.\\n\u2022\u2022 Being accepted by others.\\n\u2022\u2022 Belonging somewhere or with someone or a\\ngroup.\\n\u2022\u2022 Being with or in contact with people who love\\nor like you.\\n\u2022\u2022 Having very pleasurable sensations.\\n\u2022\u2022 Doing things that create or bring to mind\\npleasurable sensations.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Happiness\\n\u2022\u2022 Interpreting joyful events just as they are, without adding or subtracting.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Happiness\\n\u2022\u2022 Feeling excited.\\n\u2022\u2022 Feeling physically energetic, active.\\n\u2022\u2022 Feeling like giggling or laughing.\\n\u2022\u2022 Feeling your face flush.\\n\u2022\u2022 Feeling calm all the way through.\\n\u2022\u2022 Urge to keep doing what is associated with\\nhappiness.\\n\u2022\u2022 Feeling at peace.\\n\u2022\u2022 Feeling open or expansive.\\n\u2022\u2022 Other:\\nExpressions and Actions of Happiness\\n\u2022\u2022 Smiling.\\n\u2022\u2022 Having a bright, glowing face.\\n\u2022\u2022 Being bouncy or bubbly.\\n\u2022\u2022 Communicating your good feelings.\\n\u2022\u2022 Sharing the feeling.\\n\u2022\u2022 Silliness.\\n\u2022\u2022 Hugging people.\\n\u2022\u2022 Jumping up and down.\\n\u2022\u2022 Saying positive things.\\n\u2022\u2022 Using an enthusiastic or excited voice.\\n\u2022\u2022 Being talkative or talking a lot.\\n\u2022\u2022 Other:\\nAftereffects of Happiness\\n\u2022\u2022 Being courteous or friendly to others.\\n\u2022\u2022 Doing nice things for other people.\\n\u2022\u2022 Having a positive outlook; seeing the bright\\nside.\\n\u2022\u2022 Having a high threshold for worry or\\nannoyance.\\n\u2022\u2022 Remembering and imagining other times you\\nhave felt joyful.\\n\u2022\u2022 Expecting to feel joyful in the future.\\n\u2022\u2022 Other: (continued on next page)\"},{\"pdf_page\":243,\"book_page\":\"219\",\"text\":\"219\\nEmotion Regulation Handout 6 (p. 6 of 10)\\nJealousy Words\\njealous\\nclutching\\nfear of losing someone/\\nsomething\\nrivalrous\\nwary\\ncautious\\ndefensive\\nsuspicious\\nwatchful\\nclinging\\nmistrustful\\npossessive\\nself-protective\\nPrompting Events for Feeling Jealous\\n\u2022\u2022 An important relationship is threatened or in\\ndanger of being lost.\\n\u2022\u2022 A potential competitor pays attention to\\nsomeone you love.\\n\u2022\u2022 Someone:\\n\u2022\u2022 Is threatening to take away important things\\nin your life.\\n\u2022\u2022 Goes out with the person you like.\\n\u2022\u2022 Ignores you while talking to a friend of\\nyours.\\n\u2022\u2022 Is more attractive, outgoing, or self-\\nconfident than you.\\n\u2022\u2022 You are treated as unimportant by a person\\nyou want to be close to.\\n\u2022\u2022 Your partner tells you that he or she desires\\nmore time alone.\\n\u2022\u2022 Your partner appears to flirt with someone\\nelse.\\n\u2022\u2022 A person you are romantically involved with\\nlooks at someone else.\\n\u2022\u2022 You find the person you love is having an\\naffair with someone else.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Jealousy\\n\u2022\u2022 Believing that:\\n\u2022\u2022 Your partner does not care for you any\\nmore.\\n\u2022\u2022 You are nothing to your partner.\\n\u2022\u2022 Your partner is going to leave you.\\n\u2022\u2022 Your partner is behaving inappropriately.\\n\u2022\u2022 You don\u2019t measure up to your peers.\\n\u2022\u2022 I deserve more than what you are receiving.\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You were cheated.\\n\u2022\u2022 No one cares about you.\\n\u2022\u2022 Your rival is possessive and competitive.\\n\u2022\u2022 Your rival is insecure.\\n\u2022\u2022 Your rival is envious.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Jealousy\\n\u2022\u2022 Breathlessness.\\n\u2022\u2022 Fast heartbeat.\\n\u2022\u2022 Choking sensation, lump in throat.\\n\u2022\u2022 Muscles tensing.\\n\u2022\u2022 Teeth clenching.\\n\u2022\u2022 Becoming suspicious of others.\\n\u2022\u2022 Having injured pride.\\n\u2022\u2022 Feelings of rejection.\\n\u2022\u2022 Needing to be in control.\\n\u2022\u2022 Feeling helpless.\\n\u2022\u2022 Wanting to grasp or keep hold of what you\\nhave.\\n\u2022\u2022 Wanting to push away or eliminate your rival.\\nExpressions and Actions of Jealousy\\n\u2022\u2022 Violent behavior or threats of violence toward\\nthe person threatening to take something\\naway.\\n\u2022\u2022 Attempting to control the freedom of the\\nperson you are afraid of losing.\\n\u2022\u2022 Verbal accusations of disloyalty or\\nunfaithfulness.\\n\u2022\u2022 Spying on the person.\\n\u2022\u2022 Interrogating the person; demanding\\naccounting of time or activities.\\n\u2022\u2022 Collecting evidence of wrongdoings.\\n\u2022\u2022 Clinging; enhanced dependency.\\n\u2022\u2022 Increased or excessive demonstrations of\\nlove.\\n\u2022\u2022 Other:\\nAftereffects of Jealousy\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Seeing the worst in others.\\n\u2022\u2022 Being mistrustful across the board.\\n\u2022\u2022 Being hypervigilant to threats to your\\nrelationships.\\n\u2022\u2022 Becoming isolated or withdrawn.\\n\u2022\u2022 Other: (continued on next page)\"},{\"pdf_page\":244,\"book_page\":\"220\",\"text\":\"220\\nEmotion Regulation Handout 6 (p. 7 of 10)\\nLove Words\\nlove\\nattraction\\nenchantment\\nlimerence\\nsympathy\\nadoration\\ncaring\\nfondness\\nlonging\\ntenderness\\naffection\\ncharmed\\ninfatuation\\nlust\\nwarmth\\narousal\\ncompassion\\nkindness\\npassion\\ndesire\\nliking\\nsentimentality\\nPrompting Events for Feeling Love\\n\u2022\u2022 A person:\\n\u2022\u2022 Offers or gives you something you want,\\nneed, or desire.\\n\u2022\u2022 Does things you want or need.\\n\u2022\u2022 Does things you particularly value or\\nadmire.\\n\u2022\u2022 Feeling physically attracted to someone.\\n\u2022\u2022 Being with someone you have fun with.\\n\u2022\u2022 You spend a lot of time with a person.\\n\u2022\u2022 You share a special experience with a\\nperson.\\n\u2022\u2022 You have exceptionally good communication\\nwith a person.\\n\u2022\u2022 Other: Interpretations of Events That Prompt Feelings of Love\\n\u2022\u2022 Believing that a person loves, needs, or appreciates you.\\n\u2022\u2022 Thinking that a person is physically attractive.\\n\u2022\u2022 Judging a person\u2019s personality as wonderful, pleasing, or attractive.\\n\u2022\u2022 Believing that a person can be counted on, or will always be there for you.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Love\\n\u2022\u2022 When you are with or thinking about\\nsomeone:\\n\u2022\u2022 Feeling excited and full of energy.\\n\u2022\u2022 Fast heartbeat.\\n\u2022\u2022 Feeling self-confident.\\n\u2022\u2022 Feeling invulnerable.\\n\u2022\u2022 Feeling happy, joyful, or exuberant.\\n\u2022\u2022 Feeling warm, trusting, and secure.\\n\u2022\u2022 Feeling relaxed and calm.\\n\u2022\u2022 Wanting the best for a person.\\n\u2022\u2022 Wanting to give things to a person.\\n\u2022\u2022 Wanting to see and spend time with a person.\\n\u2022\u2022 Wanting to spend your life with a person.\\n\u2022\u2022 Wanting physical closeness or sex.\\n\u2022\u2022 Wanting emotional closeness. Expressions and Actions of Love\\n\u2022\u2022 Saying \u201cI love you.\u201d\\n\u2022\u2022 Expressing positive feelings to a person.\\n\u2022\u2022 Eye contact, mutual gaze.\\n\u2022\u2022 Touching, petting, hugging, holding, cuddling.\\n\u2022\u2022 Sexual activity.\\n\u2022\u2022 Smiling.\\n\u2022\u2022 Sharing time and experiences with someone.\\n\u2022\u2022 Doing things that the other person wants or\\nneeds.\\n\u2022\u2022 Other:\\nAftereffects of Love\\n\u2022\u2022 Only seeing a person\u2019s positive side.\\n\u2022\u2022 Feeling forgetful or distracted; daydreaming.\\n\u2022\u2022 Feeling openness and trust.\\n\u2022\u2022 Feeling \u201calive,\u201d capable.\\n\u2022\u2022 Remembering other people you have loved.\\n\u2022\u2022 Remembering other people who have loved\\nyou.\\n\u2022\u2022 Remembering other positive events.\\n\u2022\u2022 Believing in yourself; believing you are\\nwonderful, capable, competent.\\n\u2022\u2022 Other:\\n(continued on next page)\"},{\"pdf_page\":245,\"book_page\":\"221\",\"text\":\"221\\nEmotion Regulation Handout 6 (p. 8 of 10)\\nSadness Words\\nsadness\\ndisappointment\\npity\\ncrushed\\ndisconnected\\ndepression\\ndespair\\nhomesickness\\nanguish\\ndispleasure\\nsuffering\\nglumness\\ngrief\\nneglect\\ndismay\\ninsecurity\\ndejection\\nmelancholy\\nmisery\\nalienation\\nhurt\\nsorrow\\ngloom\\nalone\\nagony\\ndiscontentment\\nrejection\\ndefeat\\nloneliness\\nwoe\\ndi\\u0007straught\\nunhappiness\\nPrompting Events for Feeling Sadness\\n\u2022\u2022 Losing something or someone irretrievably.\\n\u2022\u2022 The death of someone you love.\\n\u2022\u2022 Things not being what you expected or\\nwanted.\\n\u2022\u2022 Things being worse than you expected.\\n\u2022\u2022 Being separated from someone you care for.\\n\u2022\u2022 Getting what you don\u2019t want.\\n\u2022\u2022 Not getting what you have worked for.\\n\u2022\u2022 Not getting what you believe you need in life.\\n\u2022\u2022 Being rejected, disapproved of, or excluded.\\n\u2022\u2022 Discovering that you are powerless or\\nhelpless.\\n\u2022\u2022 Being with someone else who is sad or in\\npain.\\n\u2022\u2022 Reading or hearing about other people\u2019s\\nproblems or troubles in the world.\\n\u2022\u2022 Being alone, or feeling isolated or like an\\noutsider.\\n\u2022\u2022 Thinking about everything you have not\\ngotten.\\n\u2022\u2022 Thinking about your losses.\\n\u2022\u2022 Thinking about missing someone.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Sadness\\n\u2022\u2022 Believing that a separation from someone will\\nlast for a long time or will never end.\\n\u2022\u2022 Believing that you will not get what you want\\nor need in your life.\\n\u2022\u2022 Seeing things or your life as hopeless.\\n\u2022\u2022 Believing that you are worthless or not\\nvaluable.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Sadness\\n\u2022\u2022 Feeling tired, run down, or low in energy.\\n\u2022\u2022 Feeling lethargic, listless; wanting to stay in\\nbed all day.\\n\u2022\u2022 Feeling as if nothing is pleasurable any more.\\n\u2022\u2022 Pain or hollowness in your chest or gut.\\n\u2022\u2022 Feeling empty.\\n\u2022\u2022 Feeling as if you can\u2019t stop crying, or if you\\never start crying you will never be able to\\nstop.\\n\u2022\u2022 Difficulty swallowing.\\n\u2022\u2022 Breathlessness.\\n\u2022\u2022 Dizziness.\\n\u2022\u2022 Other:\\nExpressions and Actions of Sadness\\n\u2022\u2022 Avoiding things.\\n\u2022\u2022 Acting helpless; staying in bed; being\\ninactive.\\n\u2022\u2022 Moping, brooding, or acting moody.\\n\u2022\u2022 Making slow, shuffling movements.\\n\u2022\u2022 Withdrawing from social contact.\\n\u2022\u2022 Avoiding activities that used to bring pleasure.\\n\u2022\u2022 Giving up and no longer trying to improve.\\n\u2022\u2022 Saying sad things.\\n\u2022\u2022 Talking little or not at all.\\n\u2022\u2022 Using a quiet, slow, or monotonous voice.\\n\u2022\u2022 Eyes drooping.\\n\u2022\u2022 Frowning, not smiling.\\n\u2022\u2022 Posture slumping.\\n\u2022\u2022 Sobbing, crying, whimpering.\\n\u2022\u2022 Other:\\nAftereffects of Sadness\\n\u2022\u2022 Not being able to remember happy things.\\n\u2022\u2022 Feeling irritable, touchy, or grouchy.\\n\u2022\u2022 Yearning and searching for the thing lost.\\n\u2022\u2022 Having a negative outlook.\\n\u2022\u2022 Blaming or criticizing yourself.\\n\u2022\u2022 Ruminating about sad events in the past.\\n\u2022\u2022 Insomnia.\\n\u2022\u2022 Appetite disturbance, indigestion.\\n\u2022\u2022 Other: (continued on next page)\"},{\"pdf_page\":246,\"book_page\":\"222\",\"text\":\"222\\nEmotion Regulation Handout 6 (p. 9 of 10)\\nShame Words\\nshame\\nculpability\\nembarrassment\\nmortification\\nshyness\\ncontrition\\ndiscomposure\\nhumiliation\\nself-conscious\\nPrompting Events for Feeling Shame\\n\u2022\u2022 Being rejected by people you care about.\\n\u2022\u2022 Having others find out that you have done\\nsomething wrong.\\n\u2022\u2022 Doing (or feeling or thinking) something\\nthat people you admire believe is wrong or\\nimmoral.\\n\u2022\u2022 Comparing some aspect of yourself or your\\nbehavior to a standard and feeling as if you\\ndo not live up to that standard.\\n\u2022\u2022 Being betrayed by a person you love.\\n\u2022\u2022 Being laughed at/made fun of.\\n\u2022\u2022 Being criticized in public/in front of someone\\nelse; remembering public criticism.\\n\u2022\u2022 Others attacking your integrity.\\n\u2022\u2022 Being reminded of something wrong,\\nimmoral, or \u201cshameful\u201d you did in the past.\\n\u2022\u2022 Being rejected or criticized for something you\\nexpected praise for.\\n\u2022\u2022 Having emotions/experiences that have been\\ninvalidated.\\n\u2022\u2022 Exposure of a very private aspect of yourself\\nor your life.\\n\u2022\u2022 Exposure of a physical characteristic you\\ndislike.\\n\u2022\u2022 Failing at something you feel you are (or\\nshould be) competent to do.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Shame\\n\u2022\u2022 Believing that others will reject you (or have\\nrejected you).\\n\u2022\u2022 Judging yourself to be inferior, not \u201cgood\\nenough,\u201d not as good as others; self-\\ninvalidation.\\n\u2022\u2022 Comparing yourself to others and thinking\\nthat you are a \u201closer.\u201d\\n\u2022\u2022 Believing yourself unlovable.\\n\u2022\u2022 Thinking that you are bad, immoral, or wrong.\\n\u2022\u2022 Thinking that you are defective.\\n\u2022\u2022 Thinking that you are a bad person or a\\nfailure.\\n\u2022\u2022 Believing your body (or a body part) is too\\nbig, too small, or ugly.\\n\u2022\u2022 Thinking that you have not lived up to others\u2019\\nexpectations of you.\\n\u2022\u2022 Thinking that your behavior, thoughts, or\\nfeelings are silly or stupid.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Shame\\n\u2022\u2022 Pain in the pit of the stomach.\\n\u2022\u2022 Sense of dread.\\n\u2022\u2022 Wanting to shrink down and/or disappear.\\n\u2022\u2022 Wanting to hide or cover your face and body.\\n\u2022\u2022 Other:\\nExpressions and Actions of Shame\\n\u2022\u2022 Hiding behavior or a characteristic from other\\npeople.\\n\u2022\u2022 Avoiding the person you have harmed.\\n\u2022\u2022 Avoiding persons who have criticized you.\\n\u2022\u2022 Avoiding yourself\u2014distracting, ignoring.\\n\u2022\u2022 Withdrawing; covering the face.\\n\u2022\u2022 Bowing your head, groveling.\\n\u2022\u2022 Appeasing; saying you are sorry over and\\nover and over.\\n\u2022\u2022 Looking down and away from others.\\n\u2022\u2022 Sinking back; slumped and rigid posture.\\n\u2022\u2022 Halting speech; lowered volume while talking.\\n\u2022\u2022 Other:\\nAftereffects of Shame\\n\u2022\u2022 Avoiding thinking about your transgression;\\nshutting down; blocking all emotions.\\n\u2022\u2022 Engaging in distracting, impulsive behaviors\\nto divert your mind or attention.\\n\u2022\u2022 High amount of \u201cself-focus\u201d; preoccupation\\nwith yourself.\\n\u2022\u2022 Depersonalization, dissociative experiences,\\nnumbness, or shock.\\n\u2022\u2022 Attacking or blaming others.\\n\u2022\u2022 Conflicts with other people.\\n\u2022\u2022 Isolation, feeling alienated.\\n\u2022\u2022 Impairment in problem-solving ability.\\n\u2022\u2022 Other: (continued on next page)\"}],\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"ourspace_shared_revision_metadata\":{\"source_path\":\"DBT+ADHD Skill Files/04_DBT_Emotion_Regulation/handouts/json/emotion_regulation_handout_6_ways_to_describe_emotions_anger_words_anger_bitterness.json\",\"shared_output_path\":\"shared/04_dbt_emotion_regulation/handouts_json/emotion_regulation_handout_6_ways_to_describe_emotions_anger_words_anger_26020865.json\",\"revised_at_utc\":\"2026-06-26T00:24:16Z\",\"copyright_note\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\"},\"source_marker\":{\"_merged_values\":[\"Emotion Regulation Handout 6   (Emotion Regulation Worksheets 4, 4a) (p. 1 of 10)\",\"Emotion Regulation Handout 6 (Emotion Regulation Worksheets 4, 4a) (p. 1 of 10)\"]},\"source_pdf_pages\":[238,239,240,241,242,243,244,245,246],\"fillable_html_created\":false,\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/emotion_regulation/handouts/emotion_regulation_handout_6_ways_to_describe_emotions_anger_words_anger_bitterness.json\",\"item_number\":\"6\",\"full_text\":{\"_merged_values\":[\"\u2610\\nEmotion Regulation Handout 6   (Emotion Regulation Worksheets 4, 4a) (p. 1 of 10)\\nWays to Describe Emotions\\nAnger Words\\nanger\\nbitterness\\nfury\\nindignation\\nvengefulness\\naggravation\\nexasperation\\ngrouchiness\\nirritation\\nwrath\\nagitation\\nferocity\\ngrumpiness\\noutrage\\nannoyance\\nfrustration\\nhostility\\nrage\\nPrompting Events for Feeling Anger\\n\u2022\u2022 Having an important goal blocked.\\n\u2022\u2022 You or someone you care about being\\nattacked or threatened by others.\\n\u2022\u2022 Losing power, status, or respect.\\n\u2022\u2022 Not having things turn out as expected.\\n\u2022\u2022 Physical or emotional pain.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Anger\\n\u2022\u2022 Believing that you have been treated unfairly.\\n\u2022\u2022 Blaming.\\n\u2022\u2022 Believing that important goals are being\\nblocked or stopped.\\n\u2022\u2022 Believing that things \u201cshould\u201d be different\\nthan they are.\\n\u2022\u2022 Rigidly thinking, \u201cI\u2019m right.\u201d\\n\u2022\u2022 Judging that the situation is illegitimate or\\nwrong.\\n\u2022\u2022 Ruminating about the event that set off the\\nanger in the first place.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Anger\\n\u2022\u2022 Muscles tightening.\\n\u2022\u2022 Teeth clamping together.\\n\u2022\u2022 Hands clenching.\\n\u2022\u2022 Feeling your face flush or get hot.\\n\u2022\u2022 Feeling like you are going to explode.\\n\u2022\u2022 Being unable to stop tears.\\n\u2022\u2022 Wanting to hit someone, bang the wall, throw\\nsomething, blow up.\\n\u2022\u2022 Wanting to hurt someone.\\n\u2022\u2022 Other:\\nExpressions and Actions of Anger\\n\u2022\u2022 Physically or verbally attacking.\\n\u2022\u2022 Making aggressive or threatening gestures.\\n\u2022\u2022 Pounding, throwing things, breaking things.\\n\u2022\u2022 Walking heavily, stomping, slamming doors.\\n\u2022\u2022 Walking out.\\n\u2022\u2022 Using a loud, quarrelsome, or sarcastic voice.\\n\u2022\u2022 Using obscenities or swearing.\\n\u2022\u2022 Criticizing or complaining.\\n\u2022\u2022 Clenching your hands or fists.\\n\u2022\u2022 Frowning, not smiling, mean expression.\\n\u2022\u2022 Brooding or withdrawing from others.\\n\u2022\u2022 Crying.\\n\u2022\u2022 Grinning.\\n\u2022\u2022 A red or flushed face.\\n\u2022\u2022 Other:\\nAftereffects of Anger\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Attending only to the situation that\u2019s making\\nyou angry.\\n\u2022\u2022 Ruminating about the situation making you\\nangry or about situations in the past.\\n\u2022\u2022 Imagining future situations that will make you\\nangry.\\n\u2022\u2022 Depersonalization, dissociative experiences,\\nnumbness.\\n\u2022\u2022 Other:\\n(continued on next page)\\nNote. Adapted from Table 3 in Shaver, P., Schwartz, J., Kirson, D., & O\u2019Connor, C. (1987). Emotion knowledge: Further exploration of a proto-\\ntype approach. Journal of Personality and Social Psychology, 52(6), 1061\u20131086. Copyright 1987 by the American Psychological Association.\\nAdapted by permission.\\n\\nEmotion Regulation Handout 6   (p. 2 of 10)\\nDisgust Words\\ndisgust\\naversion\\ndislike\\ndistaste\\nrepugnance\\nresentment\\nsickened\\nabhorrence\\ncondescension\\nderision\\nhate\\nrepelled\\nrevolted\\nspite\\nantipathy\\ncontempt\\ndisdain\\nloathing\\nrepulsion\\nscorn\\nvile\\nPrompting Events for Feeling Disgust\\n\u2022\u2022 Seeing/smelling human or animal waste\\nproducts.\\n\u2022\u2022 Having a person or an animal that is dirty,\\nslimy, or unclean come close to you.\\n\u2022\u2022 Tasting something or being forced to swallow\\nsomething you really don\u2019t want.\\n\u2022\u2022 Seeing or being near a dead body.\\n\u2022\u2022 Touching items worn or owned by a stranger,\\ndead person, or disliked person.\\n\u2022\u2022 Observing or hearing about a person who\\ngrovels or who strips another person of\\ndignity.\\n\u2022\u2022 Seeing blood; getting blood drawn.\\n\u2022\u2022 Observing or hearing about a person acting\\nwith extreme hypocrisy/fawning.\\n\u2022\u2022 Observing or hearing about betrayal, child\\nabuse, racism, or other types of cruelty.\\n\u2022\u2022 Being forced to watch something that deeply\\nviolates your own Wise Mind values.\\n\u2022\u2022 Being confronted with someone who is\\ndeeply violating your own Wise Mind values.\\n\u2022\u2022 Being forced to engage in or watch unwanted\\nsexual contact.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Disgust\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You are swallowing something toxic.\\n\u2022\u2022 Your skin or your mind is being\\ncontaminated.\\n\u2022\u2022 Your own body or body parts are ugly.\\n\u2022\u2022 Others are evil or the \u201cscum\u201d of the earth,\\nor that they disrespect authority or the\\ngroup.\\n\u2022\u2022 Disapproving of/feeling morally superior to\\nanother.\\n\u2022\u2022 Extreme disapproval of yourself or your own\\nfeelings, thoughts, or behaviors.\\n\u2022\u2022 Judging that a person is deeply immoral or\\nhas sinned or violated the natural order of\\nthings.\\n\u2022\u2022 Judging someone\u2019s body as extremely ugly.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Disgust\\n\u2022\u2022 Feelings of nausea; sick feeling.\\n\u2022\u2022 Urge to vomit, vomiting, gagging, choking.\\n\u2022\u2022 Having a lump in your throat.\\n\u2022\u2022 Aversion to drinking or eating.\\n\u2022\u2022 Intense urge to destroy or get rid of\\nsomething.\\n\u2022\u2022 Urge to take a shower.\\n\u2022\u2022 Urge to run away or push away.\\n\u2022\u2022 Feeling contaminated, dirty, unclean.\\n\u2022\u2022 Feeling mentally polluted.\\n\u2022\u2022 Fainting.\\n\u2022\u2022 Other:\\nExpressions and Actions of Disgust\\n\u2022\u2022 Vomiting, spitting out.\\n\u2022\u2022 Closing your eyes, looking away.\\n\u2022\u2022 Washing, scrubbing, taking a bath.\\n\u2022\u2022 Changing your clothes; cleaning spaces.\\n\u2022\u2022 Avoiding eating or drinking.\\n\u2022\u2022 Pushing or kicking away; running away.\\n\u2022\u2022 Treating with disdain or disrespect.\\n\u2022\u2022 Stepping over; crowding another person out.\\n\u2022\u2022 Physically attacking causes of your disgust.\\n\u2022\u2022 Using obscenities or cursing.\\n\u2022\u2022 Clenching your hands or fists.\\n\u2022\u2022 Frowning, or not smiling.\\n\u2022\u2022 Mean or unpleasant facial expression.\\n\u2022\u2022 Speaking with a sarcastic voice tone.\\n\u2022\u2022 Nose and top lip tightened up; smirking.\\n\u2022\u2022 Other:\\nAftereffects of Disgust\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Ruminating about the situation that\u2019s making\\nyou feel disgusted.\\n\u2022\u2022 Becoming hypersensitive to dirt.\\n\u2022\u2022 Other:\\n(continued on next page)\\n\\nEmotion Regulation Handout 6   (p. 3 of 10)\\nEnvy Words\\nenvy\\ncraving\\ndispleased\\ngreed\\npettiness\\nbitterness\\ndiscontented\\ndissatisfied\\n\u201cgreen-eyed\u201d\\nresentment\\ncovetous\\ndisgruntled\\ndown-hearted\\nlonging\\nwishful\\nPrompting Events for Feeling Envy\\n\u2022\u2022 Someone has something you really want or\\nneed but don\u2019t or can\u2019t have.\\n\u2022\u2022 You are not part of the \u201cin\u201d crowd.\\n\u2022\u2022 Someone appears to have everything.\\n\u2022\u2022 You are alone while others are having fun.\\n\u2022\u2022 Someone else gets credit for what you\u2019ve\\ndone.\\n\u2022\u2022 Someone gets positive recognition for\\nsomething and you don\u2019t.\\n\u2022\u2022 Others get something you really want and\\nyou don\u2019t get it.\\n\u2022\u2022 Being around people who have more than\\nyou have.\\n\u2022\u2022 Someone you are competing with is more\\nsuccessful than you in an area important to\\nyou.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Envy\\n\u2022\u2022 Thinking you deserve what others have.\\n\u2022\u2022 Thinking others have more than you.\\n\u2022\u2022 Thinking about how unfair it is that you have\\nsuch a bad lot in life compared to others.\\n\u2022\u2022 Thinking you have been treated unfairly by\\nlife.\\n\u2022\u2022 Thinking you are unlucky.\\n\u2022\u2022 Thinking you are inferior, a failure, or\\nmediocre in comparison to others whom you\\nwant to be like.\\n\u2022\u2022 Comparing yourself to others who have more\\nthan you.\\n\u2022\u2022 Comparing yourself to people who have\\ncharacteristics that you wish you had.\\n\u2022\u2022 Thinking you are unappreciated.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Envy\\n\u2022\u2022 Muscles tightening.\\n\u2022\u2022 Teeth clamping together, mouth tightening.\\n\u2022\u2022 Feeling your face flush or get hot.\\n\u2022\u2022 Feeling rigidity in your body.\\n\u2022\u2022 Pain in the pit of the stomach.\\n\u2022\u2022 Having an urge to get even.\\n\u2022\u2022 Hating the other person.\\n\u2022\u2022 Wanting to hurt the people you envy.\\n\u2022\u2022 Wanting the person or people you envy to\\nlose what they have, to have bad luck, or to\\nbe hurt.\\n\u2022\u2022 Feeling pleasure when others experience\\nfailure or lose what they have.\\n\u2022\u2022 Feeling unhappy if another person\\nexperiences some good luck.\\n\u2022\u2022 Feeling motivated to improve yourself.\\n\u2022\u2022 Other:\\nExpressions and Actions of Envy\\n\u2022\u2022 Doing everything you can to get what the\\nother person has.\\n\u2022\u2022 Working a lot harder than you were to get\\nwhat you want.\\n\u2022\u2022 Trying to improve yourself and your situation.\\n\u2022\u2022 Taking away or ruining what the other person\\nhas.\\n\u2022\u2022 Attacking or criticizing the other person.\\n\u2022\u2022 Doing something to get even.\\n\u2022\u2022 Doing something to make the other person\\nfail or lose what he or she has.\\n\u2022\u2022 Saying mean things about the other person\\nor making the person look bad to others.\\n\u2022\u2022 Trying to show the other person up, to look\\nbetter than the other person.\\n\u2022\u2022 Avoiding persons who have what you want.\\n\u2022\u2022 Other:\\nAftereffects of Envy\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Attending only to what others have that you\\ndon\u2019t.\\n\u2022\u2022 Ruminating when others have had more than\\nyou.\\n\u2022\u2022 Discounting what you do have; not\\nappreciating things you have or things others\\ndo for you.\\n\u2022\u2022 Ruminating about what you don\u2019t have.\\n\u2022\u2022 Making resolutions to change.\\n\u2022\u2022 Other:\\n\\n(continued on next page)\\n\\nEmotion Regulation Handout 6   (p. 4 of 10)\\nFear Words\\nfear\\ndread\\nhorror\\nnervousness\\nshock\\nuneasiness\\nanxiety\\nedginess\\nhysteria\\noverwhelmed\\ntenseness\\nworry\\napprehension\\nfright\\njumpiness\\npanic\\nterror\\nPrompting Events for Feeling Fear\\n\u2022\u2022 Having your life, your health, or your well-\\nbeing threatened.\\n\u2022\u2022 Being in the same situation (or a similar one)\\nwhere you have been threatened or gotten\\nhurt in the past, or where painful things have\\nhappened.\\n\u2022\u2022 Flashbacks.\\n\u2022\u2022 Being in situations where you have seen\\nothers threatened or be hurt.\\n\u2022\u2022 Silence.\\n\u2022\u2022 Being in a new or unfamiliar situation.\\n\u2022\u2022 Being alone (e.g., walking alone, being home\\nalone, living alone).\\n\u2022\u2022 Being in the dark.\\n\u2022\u2022 Being in crowds.\\n\u2022\u2022 Leaving your home.\\n\u2022\u2022 Having to perform in front of others.\\n\u2022\u2022 Pursuing your dreams.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Fear\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You might die, or you are going to die.\\n\u2022\u2022 You might be hurt or harmed.\\n\u2022\u2022 You might lose something valuable.\\n\u2022\u2022 Someone might reject, criticize, or dislike\\nyou.\\n\u2022\u2022 You will embarrass yourself.\\n\u2022\u2022 Failure is possible; expecting to fail.\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You will not get help you want or need.\\n\u2022\u2022 You might lose help you already have.\\n\u2022\u2022 You might lose someone important.\\n\u2022\u2022 You might lose something you want.\\n\u2022\u2022 You are helpless or are losing a sense of\\ncontrol.\\n\u2022\u2022 You are incompetent or are losing mastery.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Fear\\n\u2022\u2022 Breathlessness.\\n\u2022\u2022 Fast heartbeat.\\n\u2022\u2022 Choking sensation, lump in throat.\\n\u2022\u2022 Muscles tensing, cramping.\\n\u2022\u2022 Clenching teeth.\\n\u2022\u2022 Urge to scream or call out.\\n\u2022\u2022 Feeling nauseated.\\n\u2022\u2022 Getting cold; feeling clammy.\\n\u2022\u2022 Feeling your hairs standing on end.\\n\u2022\u2022 Feeling of \u201cbutterflies\u201d in stomach.\\n\u2022\u2022 Wanting to run away or avoid things.\\n\u2022\u2022 Other:\\nExpressions and Actions of Fear\\n\u2022\u2022 Fleeing, running away.\\n\u2022\u2022 Running or walking hurriedly.\\n\u2022\u2022 Hiding from or avoiding what you fear.\\n\u2022\u2022 Engaging in nervous, fearful talk.\\n\u2022\u2022 Pleading or crying for help.\\n\u2022\u2022 Talking less or becoming speechless.\\n\u2022\u2022 Screaming or yelling.\\n\u2022\u2022 Darting eyes or quickly looking around.\\n\u2022\u2022 Frozen stare.\\n\u2022\u2022 Talking yourself out of doing what you fear.\\n\u2022\u2022 Freezing, or trying not to move.\\n\u2022\u2022 Crying or whimpering.\\n\u2022\u2022 Shaking, quivering, or trembling.\\n\u2022\u2022 A shaky or trembling voice.\\n\u2022\u2022 Sweating or perspiring.\\n\u2022\u2022 Diarrhea, vomiting.\\n\u2022\u2022 Hair erect.\\n\u2022\u2022 Other:\\nAftereffects of Fear\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Being hypervigilant to threat.\\n\u2022\u2022 Losing your ability to focus or becoming\\ndisoriented or dazed.\\n\u2022\u2022 Losing control.\\n\u2022\u2022 Imagining the possibility of more loss or\\nfailure.\\n\u2022\u2022 Isolating yourself.\\n\u2022\u2022 Ruminating about other threatening times.\\n\u2022\u2022 Other:\\n(continued on next page)\\n\\nEmotion Regulation Handout 6   (p. 5 of 10)\\nHappiness Words\\nhappiness\\nsatisfaction\\njoviality\\nexhilaration\\necstasy\\njoy\\nbliss\\ntriumph\\noptimism\\ngladness\\nenjoyment\\nenthusiasm\\ncontentment\\nzest\\npride\\nrelief\\njolliness\\nexcitement\\neagerness\\nelation\\namusement\\nthrill\\njubilation\\ngaiety\\nglee\\nenthrallment\\ncheerfulness\\nzaniness\\npleasure\\nrapture\\nhope\\neuphoria\\ndelight\\nzeal\\nPrompting Events for Feeling Happiness\\n\u2022\u2022 Receiving a wonderful surprise.\\n\u2022\u2022 Reality exceeding your expectations.\\n\u2022\u2022 Getting what you want.\\n\u2022\u2022 Getting something you have worked hard for\\nor worried about.\\n\u2022\u2022 Things turning out better than you thought\\nthey would.\\n\u2022\u2022 Being successful at a task.\\n\u2022\u2022 Achieving a desirable outcome.\\n\u2022\u2022 Receiving esteem, respect, or praise.\\n\u2022\u2022 Receiving love, liking, or affection.\\n\u2022\u2022 Being accepted by others.\\n\u2022\u2022 Belonging somewhere or with someone or a\\ngroup.\\n\u2022\u2022 Being with or in contact with people who love\\nor like you.\\n\u2022\u2022 Having very pleasurable sensations.\\n\u2022\u2022 Doing things that create or bring to mind\\npleasurable sensations.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Happiness\\n\u2022\u2022 Interpreting joyful events just as they are, without adding or subtracting.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Happiness\\n\u2022\u2022 Feeling excited.\\n\u2022\u2022 Feeling physically energetic, active.\\n\u2022\u2022 Feeling like giggling or laughing.\\n\u2022\u2022 Feeling your face flush.\\n\u2022\u2022 Feeling calm all the way through.\\n\u2022\u2022 Urge to keep doing what is associated with\\nhappiness.\\n\u2022\u2022 Feeling at peace.\\n\u2022\u2022 Feeling open or expansive.\\n\u2022\u2022 Other:\\nExpressions and Actions of Happiness\\n\u2022\u2022 Smiling.\\n\u2022\u2022 Having a bright, glowing face.\\n\u2022\u2022 Being bouncy or bubbly.\\n\u2022\u2022 Communicating your good feelings.\\n\u2022\u2022 Sharing the feeling.\\n\u2022\u2022 Silliness.\\n\u2022\u2022 Hugging people.\\n\u2022\u2022 Jumping up and down.\\n\u2022\u2022 Saying positive things.\\n\u2022\u2022 Using an enthusiastic or excited voice.\\n\u2022\u2022 Being talkative or talking a lot.\\n\u2022\u2022 Other:\\nAftereffects of Happiness\\n\u2022\u2022 Being courteous or friendly to others.\\n\u2022\u2022 Doing nice things for other people.\\n\u2022\u2022 Having a positive outlook; seeing the bright\\nside.\\n\u2022\u2022 Having a high threshold for worry or\\nannoyance.\\n\u2022\u2022 Remembering and imagining other times you\\nhave felt joyful.\\n\u2022\u2022 Expecting to feel joyful in the future.\\n\u2022\u2022 Other:\\n\\n(continued on next page)\\n\\nEmotion Regulation Handout 6   (p. 6 of 10)\\nJealousy Words\\njealous\\nclutching\\nfear of losing someone/\\nsomething\\nrivalrous\\nwary\\ncautious\\ndefensive\\nsuspicious\\nwatchful\\nclinging\\nmistrustful\\npossessive\\nself-protective\\nPrompting Events for Feeling Jealous\\n\u2022\u2022 An important relationship is threatened or in\\ndanger of being lost.\\n\u2022\u2022 A potential competitor pays attention to\\nsomeone you love.\\n\u2022\u2022 Someone:\\n\u2022\u2022 Is threatening to take away important things\\nin your life.\\n\u2022\u2022 Goes out with the person you like.\\n\u2022\u2022 Ignores you while talking to a friend of\\nyours.\\n\u2022\u2022 Is more attractive, outgoing, or self-\\nconfident than you.\\n\u2022\u2022 You are treated as unimportant by a person\\nyou want to be close to.\\n\u2022\u2022 Your partner tells you that he or she desires\\nmore time alone.\\n\u2022\u2022 Your partner appears to flirt with someone\\nelse.\\n\u2022\u2022 A person you are romantically involved with\\nlooks at someone else.\\n\u2022\u2022 You find the person you love is having an\\naffair with someone else.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Jealousy\\n\u2022\u2022 Believing that:\\n\u2022\u2022 Your partner does not care for you any\\nmore.\\n\u2022\u2022 You are nothing to your partner.\\n\u2022\u2022 Your partner is going to leave you.\\n\u2022\u2022 Your partner is behaving inappropriately.\\n\u2022\u2022 You don\u2019t measure up to your peers.\\n\u2022\u2022 I deserve more than what you are receiving.\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You were cheated.\\n\u2022\u2022 No one cares about you.\\n\u2022\u2022 Your rival is possessive and competitive.\\n\u2022\u2022 Your rival is insecure.\\n\u2022\u2022 Your rival is envious.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Jealousy\\n\u2022\u2022 Breathlessness.\\n\u2022\u2022 Fast heartbeat.\\n\u2022\u2022 Choking sensation, lump in throat.\\n\u2022\u2022 Muscles tensing.\\n\u2022\u2022 Teeth clenching.\\n\u2022\u2022 Becoming suspicious of others.\\n\u2022\u2022 Having injured pride.\\n\u2022\u2022 Feelings of rejection.\\n\u2022\u2022 Needing to be in control.\\n\u2022\u2022 Feeling helpless.\\n\u2022\u2022 Wanting to grasp or keep hold of what you\\nhave.\\n\u2022\u2022 Wanting to push away or eliminate your rival.\\nExpressions and Actions of Jealousy\\n\u2022\u2022 Violent behavior or threats of violence toward\\nthe person threatening to take something\\naway.\\n\u2022\u2022 Attempting to control the freedom of the\\nperson you are afraid of losing.\\n\u2022\u2022 Verbal accusations of disloyalty or\\nunfaithfulness.\\n\u2022\u2022 Spying on the person.\\n\u2022\u2022 Interrogating the person; demanding\\naccounting of time or activities.\\n\u2022\u2022 Collecting evidence of wrongdoings.\\n\u2022\u2022 Clinging; enhanced dependency.\\n\u2022\u2022 Increased or excessive demonstrations of\\nlove.\\n\u2022\u2022 Other:\\nAftereffects of Jealousy\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Seeing the worst in others.\\n\u2022\u2022 Being mistrustful across the board.\\n\u2022\u2022 Being hypervigilant to threats to your\\nrelationships.\\n\u2022\u2022 Becoming isolated or withdrawn.\\n\u2022\u2022 Other:\\n\\n(continued on next page)\\n\\nEmotion Regulation Handout 6   (p. 7 of 10)\\nLove Words\\nlove\\nattraction\\nenchantment\\nlimerence\\nsympathy\\nadoration\\ncaring\\nfondness\\nlonging\\ntenderness\\naffection\\ncharmed\\ninfatuation\\nlust\\nwarmth\\narousal\\ncompassion\\nkindness\\npassion\\ndesire\\nliking\\nsentimentality\\nPrompting Events for Feeling Love\\n\u2022\u2022 A person:\\n\u2022\u2022 Offers or gives you something you want,\\nneed, or desire.\\n\u2022\u2022 Does things you want or need.\\n\u2022\u2022 Does things you particularly value or\\nadmire.\\n\u2022\u2022 Feeling physically attracted to someone.\\n\u2022\u2022 Being with someone you have fun with.\\n\u2022\u2022 You spend a lot of time with a person.\\n\u2022\u2022 You share a special experience with a\\nperson.\\n\u2022\u2022 You have exceptionally good communication\\nwith a person.\\n\u2022\u2022 Other:\\n\\nInterpretations of Events That Prompt Feelings of Love\\n\u2022\u2022 Believing that a person loves, needs, or appreciates you.\\n\u2022\u2022 Thinking that a person is physically attractive.\\n\u2022\u2022 Judging a person\u2019s personality as wonderful, pleasing, or attractive.\\n\u2022\u2022 Believing that a person can be counted on, or will always be there for you.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Love\\n\u2022\u2022 When you are with or thinking about\\nsomeone:\\n\u2022\u2022 Feeling excited and full of energy.\\n\u2022\u2022 Fast heartbeat.\\n\u2022\u2022 Feeling self-confident.\\n\u2022\u2022 Feeling invulnerable.\\n\u2022\u2022 Feeling happy, joyful, or exuberant.\\n\u2022\u2022 Feeling warm, trusting, and secure.\\n\u2022\u2022 Feeling relaxed and calm.\\n\u2022\u2022 Wanting the best for a person.\\n\u2022\u2022 Wanting to give things to a person.\\n\u2022\u2022 Wanting to see and spend time with a person.\\n\u2022\u2022 Wanting to spend your life with a person.\\n\u2022\u2022 Wanting physical closeness or sex.\\n\u2022\u2022 Wanting emotional closeness.\\n\\nExpressions and Actions of Love\\n\u2022\u2022 Saying \u201cI love you.\u201d\\n\u2022\u2022 Expressing positive feelings to a person.\\n\u2022\u2022 Eye contact, mutual gaze.\\n\u2022\u2022 Touching, petting, hugging, holding, cuddling.\\n\u2022\u2022 Sexual activity.\\n\u2022\u2022 Smiling.\\n\u2022\u2022 Sharing time and experiences with someone.\\n\u2022\u2022 Doing things that the other person wants or\\nneeds.\\n\u2022\u2022 Other:\\nAftereffects of Love\\n\u2022\u2022 Only seeing a person\u2019s positive side.\\n\u2022\u2022 Feeling forgetful or distracted; daydreaming.\\n\u2022\u2022 Feeling openness and trust.\\n\u2022\u2022 Feeling \u201calive,\u201d capable.\\n\u2022\u2022 Remembering other people you have loved.\\n\u2022\u2022 Remembering other people who have loved\\nyou.\\n\u2022\u2022 Remembering other positive events.\\n\u2022\u2022 Believing in yourself; believing you are\\nwonderful, capable, competent.\\n\u2022\u2022 Other:\\n(continued on next page)\\n\\nEmotion Regulation Handout 6   (p. 8 of 10)\\nSadness Words\\nsadness\\ndisappointment\\npity\\ncrushed\\ndisconnected\\ndepression\\ndespair\\nhomesickness\\nanguish\\ndispleasure\\nsuffering\\nglumness\\ngrief\\nneglect\\ndismay\\ninsecurity\\ndejection\\nmelancholy\\nmisery\\nalienation\\nhurt\\nsorrow\\ngloom\\nalone\\nagony\\ndiscontentment\\nrejection\\ndefeat\\nloneliness\\nwoe\\ndi\\u0007straught\\nunhappiness\\nPrompting Events for Feeling Sadness\\n\u2022\u2022 Losing something or someone irretrievably.\\n\u2022\u2022 The death of someone you love.\\n\u2022\u2022 Things not being what you expected or\\nwanted.\\n\u2022\u2022 Things being worse than you expected.\\n\u2022\u2022 Being separated from someone you care for.\\n\u2022\u2022 Getting what you don\u2019t want.\\n\u2022\u2022 Not getting what you have worked for.\\n\u2022\u2022 Not getting what you believe you need in life.\\n\u2022\u2022 Being rejected, disapproved of, or excluded.\\n\u2022\u2022 Discovering that you are powerless or\\nhelpless.\\n\u2022\u2022 Being with someone else who is sad or in\\npain.\\n\u2022\u2022 Reading or hearing about other people\u2019s\\nproblems or troubles in the world.\\n\u2022\u2022 Being alone, or feeling isolated or like an\\noutsider.\\n\u2022\u2022 Thinking about everything you have not\\ngotten.\\n\u2022\u2022 Thinking about your losses.\\n\u2022\u2022 Thinking about missing someone.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Sadness\\n\u2022\u2022 Believing that a separation from someone will\\nlast for a long time or will never end.\\n\u2022\u2022 Believing that you will not get what you want\\nor need in your life.\\n\u2022\u2022 Seeing things or your life as hopeless.\\n\u2022\u2022 Believing that you are worthless or not\\nvaluable.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Sadness\\n\u2022\u2022 Feeling tired, run down, or low in energy.\\n\u2022\u2022 Feeling lethargic, listless; wanting to stay in\\nbed all day.\\n\u2022\u2022 Feeling as if nothing is pleasurable any more.\\n\u2022\u2022 Pain or hollowness in your chest or gut.\\n\u2022\u2022 Feeling empty.\\n\u2022\u2022 Feeling as if you can\u2019t stop crying, or if you\\never start crying you will never be able to\\nstop.\\n\u2022\u2022 Difficulty swallowing.\\n\u2022\u2022 Breathlessness.\\n\u2022\u2022 Dizziness.\\n\u2022\u2022 Other:\\nExpressions and Actions of Sadness\\n\u2022\u2022 Avoiding things.\\n\u2022\u2022 Acting helpless; staying in bed; being\\ninactive.\\n\u2022\u2022 Moping, brooding, or acting moody.\\n\u2022\u2022 Making slow, shuffling movements.\\n\u2022\u2022 Withdrawing from social contact.\\n\u2022\u2022 Avoiding activities that used to bring pleasure.\\n\u2022\u2022 Giving up and no longer trying to improve.\\n\u2022\u2022 Saying sad things.\\n\u2022\u2022 Talking little or not at all.\\n\u2022\u2022 Using a quiet, slow, or monotonous voice.\\n\u2022\u2022 Eyes drooping.\\n\u2022\u2022 Frowning, not smiling.\\n\u2022\u2022 Posture slumping.\\n\u2022\u2022 Sobbing, crying, whimpering.\\n\u2022\u2022 Other:\\nAftereffects of Sadness\\n\u2022\u2022 Not being able to remember happy things.\\n\u2022\u2022 Feeling irritable, touchy, or grouchy.\\n\u2022\u2022 Yearning and searching for the thing lost.\\n\u2022\u2022 Having a negative outlook.\\n\u2022\u2022 Blaming or criticizing yourself.\\n\u2022\u2022 Ruminating about sad events in the past.\\n\u2022\u2022 Insomnia.\\n\u2022\u2022 Appetite disturbance, indigestion.\\n\u2022\u2022 Other:\\n\\n(continued on next page)\\n\\nEmotion Regulation Handout 6   (p. 9 of 10)\\nShame Words\\nshame\\nculpability\\nembarrassment\\nmortification\\nshyness\\ncontrition\\ndiscomposure\\nhumiliation\\nself-conscious\\nPrompting Events for Feeling Shame\\n\u2022\u2022 Being rejected by people you care about.\\n\u2022\u2022 Having others find out that you have done\\nsomething wrong.\\n\u2022\u2022 Doing (or feeling or thinking) something\\nthat people you admire believe is wrong or\\nimmoral.\\n\u2022\u2022 Comparing some aspect of yourself or your\\nbehavior to a standard and feeling as if you\\ndo not live up to that standard.\\n\u2022\u2022 Being betrayed by a person you love.\\n\u2022\u2022 Being laughed at/made fun of.\\n\u2022\u2022 Being criticized in public/in front of someone\\nelse; remembering public criticism.\\n\u2022\u2022 Others attacking your integrity.\\n\u2022\u2022 Being reminded of something wrong,\\nimmoral, or \u201cshameful\u201d you did in the past.\\n\u2022\u2022 Being rejected or criticized for something you\\nexpected praise for.\\n\u2022\u2022 Having emotions/experiences that have been\\ninvalidated.\\n\u2022\u2022 Exposure of a very private aspect of yourself\\nor your life.\\n\u2022\u2022 Exposure of a physical characteristic you\\ndislike.\\n\u2022\u2022 Failing at something you feel you are (or\\nshould be) competent to do.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Shame\\n\u2022\u2022 Believing that others will reject you (or have\\nrejected you).\\n\u2022\u2022 Judging yourself to be inferior, not \u201cgood\\nenough,\u201d not as good as others; self-\\ninvalidation.\\n\u2022\u2022 Comparing yourself to others and thinking\\nthat you are a \u201closer.\u201d\\n\u2022\u2022 Believing yourself unlovable.\\n\u2022\u2022 Thinking that you are bad, immoral, or wrong.\\n\u2022\u2022 Thinking that you are defective.\\n\u2022\u2022 Thinking that you are a bad person or a\\nfailure.\\n\u2022\u2022 Believing your body (or a body part) is too\\nbig, too small, or ugly.\\n\u2022\u2022 Thinking that you have not lived up to others\u2019\\nexpectations of you.\\n\u2022\u2022 Thinking that your behavior, thoughts, or\\nfeelings are silly or stupid.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Shame\\n\u2022\u2022 Pain in the pit of the stomach.\\n\u2022\u2022 Sense of dread.\\n\u2022\u2022 Wanting to shrink down and/or disappear.\\n\u2022\u2022 Wanting to hide or cover your face and body.\\n\u2022\u2022 Other:\\nExpressions and Actions of Shame\\n\u2022\u2022 Hiding behavior or a characteristic from other\\npeople.\\n\u2022\u2022 Avoiding the person you have harmed.\\n\u2022\u2022 Avoiding persons who have criticized you.\\n\u2022\u2022 Avoiding yourself\u2014distracting, ignoring.\\n\u2022\u2022 Withdrawing; covering the face.\\n\u2022\u2022 Bowing your head, groveling.\\n\u2022\u2022 Appeasing; saying you are sorry over and\\nover and over.\\n\u2022\u2022 Looking down and away from others.\\n\u2022\u2022 Sinking back; slumped and rigid posture.\\n\u2022\u2022 Halting speech; lowered volume while talking.\\n\u2022\u2022 Other:\\nAftereffects of Shame\\n\u2022\u2022 Avoiding thinking about your transgression;\\nshutting down; blocking all emotions.\\n\u2022\u2022 Engaging in distracting, impulsive behaviors\\nto divert your mind or attention.\\n\u2022\u2022 High amount of \u201cself-focus\u201d; preoccupation\\nwith yourself.\\n\u2022\u2022 Depersonalization, dissociative experiences,\\nnumbness, or shock.\\n\u2022\u2022 Attacking or blaming others.\\n\u2022\u2022 Conflicts with other people.\\n\u2022\u2022 Isolation, feeling alienated.\\n\u2022\u2022 Impairment in problem-solving ability.\\n\u2022\u2022 Other:\\n\\n(continued on next page)\",\"\u2610\\nEmotion Regulation Handout 6 (Emotion Regulation Worksheets 4, 4a) (p. 1 of 10)\\nWays to Describe Emotions\\nAnger Words\\nanger\\nbitterness\\nfury\\nindignation\\nvengefulness\\naggravation\\nexasperation\\ngrouchiness\\nirritation\\nwrath\\nagitation\\nferocity\\ngrumpiness\\noutrage\\nannoyance\\nfrustration\\nhostility\\nrage\\nPrompting Events for Feeling Anger\\n\u2022\u2022 Having an important goal blocked.\\n\u2022\u2022 You or someone you care about being\\nattacked or threatened by others.\\n\u2022\u2022 Losing power, status, or respect.\\n\u2022\u2022 Not having things turn out as expected.\\n\u2022\u2022 Physical or emotional pain.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Anger\\n\u2022\u2022 Believing that you have been treated unfairly.\\n\u2022\u2022 Blaming.\\n\u2022\u2022 Believing that important goals are being\\nblocked or stopped.\\n\u2022\u2022 Believing that things \u201cshould\u201d be different\\nthan they are.\\n\u2022\u2022 Rigidly thinking, \u201cI\u2019m right.\u201d\\n\u2022\u2022 Judging that the situation is illegitimate or\\nwrong.\\n\u2022\u2022 Ruminating about the event that set off the\\nanger in the first place.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Anger\\n\u2022\u2022 Muscles tightening.\\n\u2022\u2022 Teeth clamping together.\\n\u2022\u2022 Hands clenching.\\n\u2022\u2022 Feeling your face flush or get hot.\\n\u2022\u2022 Feeling like you are going to explode.\\n\u2022\u2022 Being unable to stop tears.\\n\u2022\u2022 Wanting to hit someone, bang the wall, throw\\nsomething, blow up.\\n\u2022\u2022 Wanting to hurt someone.\\n\u2022\u2022 Other:\\nExpressions and Actions of Anger\\n\u2022\u2022 Physically or verbally attacking.\\n\u2022\u2022 Making aggressive or threatening gestures.\\n\u2022\u2022 Pounding, throwing things, breaking things.\\n\u2022\u2022 Walking heavily, stomping, slamming doors.\\n\u2022\u2022 Walking out.\\n\u2022\u2022 Using a loud, quarrelsome, or sarcastic voice.\\n\u2022\u2022 Using obscenities or swearing.\\n\u2022\u2022 Criticizing or complaining.\\n\u2022\u2022 Clenching your hands or fists.\\n\u2022\u2022 Frowning, not smiling, mean expression.\\n\u2022\u2022 Brooding or withdrawing from others.\\n\u2022\u2022 Crying.\\n\u2022\u2022 Grinning.\\n\u2022\u2022 A red or flushed face.\\n\u2022\u2022 Other:\\nAftereffects of Anger\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Attending only to the situation that\u2019s making\\nyou angry.\\n\u2022\u2022 Ruminating about the situation making you\\nangry or about situations in the past.\\n\u2022\u2022 Imagining future situations that will make you\\nangry.\\n\u2022\u2022 Depersonalization, dissociative experiences,\\nnumbness.\\n\u2022\u2022 Other:\\n(continued on next page)\\nNote. Adapted from Table 3 in Shaver, P., Schwartz, J., Kirson, D., & O\u2019Connor, C. (1987). Emotion knowledge: Further exploration of a proto-\\ntype approach. Journal of Personality and Social Psychology, 52(6), 1061\u20131086. Copyright 1987 by the American Psychological Association.\\nAdapted by permission. Emotion Regulation Handout 6 (p. 2 of 10)\\nDisgust Words\\ndisgust\\naversion\\ndislike\\ndistaste\\nrepugnance\\nresentment\\nsickened\\nabhorrence\\ncondescension\\nderision\\nhate\\nrepelled\\nrevolted\\nspite\\nantipathy\\ncontempt\\ndisdain\\nloathing\\nrepulsion\\nscorn\\nvile\\nPrompting Events for Feeling Disgust\\n\u2022\u2022 Seeing/smelling human or animal waste\\nproducts.\\n\u2022\u2022 Having a person or an animal that is dirty,\\nslimy, or unclean come close to you.\\n\u2022\u2022 Tasting something or being forced to swallow\\nsomething you really don\u2019t want.\\n\u2022\u2022 Seeing or being near a dead body.\\n\u2022\u2022 Touching items worn or owned by a stranger,\\ndead person, or disliked person.\\n\u2022\u2022 Observing or hearing about a person who\\ngrovels or who strips another person of\\ndignity.\\n\u2022\u2022 Seeing blood; getting blood drawn.\\n\u2022\u2022 Observing or hearing about a person acting\\nwith extreme hypocrisy/fawning.\\n\u2022\u2022 Observing or hearing about betrayal, child\\nabuse, racism, or other types of cruelty.\\n\u2022\u2022 Being forced to watch something that deeply\\nviolates your own Wise Mind values.\\n\u2022\u2022 Being confronted with someone who is\\ndeeply violating your own Wise Mind values.\\n\u2022\u2022 Being forced to engage in or watch unwanted\\nsexual contact.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Disgust\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You are swallowing something toxic.\\n\u2022\u2022 Your skin or your mind is being\\ncontaminated.\\n\u2022\u2022 Your own body or body parts are ugly.\\n\u2022\u2022 Others are evil or the \u201cscum\u201d of the earth,\\nor that they disrespect authority or the\\ngroup.\\n\u2022\u2022 Disapproving of/feeling morally superior to\\nanother.\\n\u2022\u2022 Extreme disapproval of yourself or your own\\nfeelings, thoughts, or behaviors.\\n\u2022\u2022 Judging that a person is deeply immoral or\\nhas sinned or violated the natural order of\\nthings.\\n\u2022\u2022 Judging someone\u2019s body as extremely ugly.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Disgust\\n\u2022\u2022 Feelings of nausea; sick feeling.\\n\u2022\u2022 Urge to vomit, vomiting, gagging, choking.\\n\u2022\u2022 Having a lump in your throat.\\n\u2022\u2022 Aversion to drinking or eating.\\n\u2022\u2022 Intense urge to destroy or get rid of\\nsomething.\\n\u2022\u2022 Urge to take a shower.\\n\u2022\u2022 Urge to run away or push away.\\n\u2022\u2022 Feeling contaminated, dirty, unclean.\\n\u2022\u2022 Feeling mentally polluted.\\n\u2022\u2022 Fainting.\\n\u2022\u2022 Other:\\nExpressions and Actions of Disgust\\n\u2022\u2022 Vomiting, spitting out.\\n\u2022\u2022 Closing your eyes, looking away.\\n\u2022\u2022 Washing, scrubbing, taking a bath.\\n\u2022\u2022 Changing your clothes; cleaning spaces.\\n\u2022\u2022 Avoiding eating or drinking.\\n\u2022\u2022 Pushing or kicking away; running away.\\n\u2022\u2022 Treating with disdain or disrespect.\\n\u2022\u2022 Stepping over; crowding another person out.\\n\u2022\u2022 Physically attacking causes of your disgust.\\n\u2022\u2022 Using obscenities or cursing.\\n\u2022\u2022 Clenching your hands or fists.\\n\u2022\u2022 Frowning, or not smiling.\\n\u2022\u2022 Mean or unpleasant facial expression.\\n\u2022\u2022 Speaking with a sarcastic voice tone.\\n\u2022\u2022 Nose and top lip tightened up; smirking.\\n\u2022\u2022 Other:\\nAftereffects of Disgust\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Ruminating about the situation that\u2019s making\\nyou feel disgusted.\\n\u2022\u2022 Becoming hypersensitive to dirt.\\n\u2022\u2022 Other:\\n(continued on next page) Emotion Regulation Handout 6 (p. 3 of 10)\\nEnvy Words\\nenvy\\ncraving\\ndispleased\\ngreed\\npettiness\\nbitterness\\ndiscontented\\ndissatisfied\\n\u201cgreen-eyed\u201d\\nresentment\\ncovetous\\ndisgruntled\\ndown-hearted\\nlonging\\nwishful\\nPrompting Events for Feeling Envy\\n\u2022\u2022 Someone has something you really want or\\nneed but don\u2019t or can\u2019t have.\\n\u2022\u2022 You are not part of the \u201cin\u201d crowd.\\n\u2022\u2022 Someone appears to have everything.\\n\u2022\u2022 You are alone while others are having fun.\\n\u2022\u2022 Someone else gets credit for what you\u2019ve\\ndone.\\n\u2022\u2022 Someone gets positive recognition for\\nsomething and you don\u2019t.\\n\u2022\u2022 Others get something you really want and\\nyou don\u2019t get it.\\n\u2022\u2022 Being around people who have more than\\nyou have.\\n\u2022\u2022 Someone you are competing with is more\\nsuccessful than you in an area important to\\nyou.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Envy\\n\u2022\u2022 Thinking you deserve what others have.\\n\u2022\u2022 Thinking others have more than you.\\n\u2022\u2022 Thinking about how unfair it is that you have\\nsuch a bad lot in life compared to others.\\n\u2022\u2022 Thinking you have been treated unfairly by\\nlife.\\n\u2022\u2022 Thinking you are unlucky.\\n\u2022\u2022 Thinking you are inferior, a failure, or\\nmediocre in comparison to others whom you\\nwant to be like.\\n\u2022\u2022 Comparing yourself to others who have more\\nthan you.\\n\u2022\u2022 Comparing yourself to people who have\\ncharacteristics that you wish you had.\\n\u2022\u2022 Thinking you are unappreciated.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Envy\\n\u2022\u2022 Muscles tightening.\\n\u2022\u2022 Teeth clamping together, mouth tightening.\\n\u2022\u2022 Feeling your face flush or get hot.\\n\u2022\u2022 Feeling rigidity in your body.\\n\u2022\u2022 Pain in the pit of the stomach.\\n\u2022\u2022 Having an urge to get even.\\n\u2022\u2022 Hating the other person.\\n\u2022\u2022 Wanting to hurt the people you envy.\\n\u2022\u2022 Wanting the person or people you envy to\\nlose what they have, to have bad luck, or to\\nbe hurt.\\n\u2022\u2022 Feeling pleasure when others experience\\nfailure or lose what they have.\\n\u2022\u2022 Feeling unhappy if another person\\nexperiences some good luck.\\n\u2022\u2022 Feeling motivated to improve yourself.\\n\u2022\u2022 Other:\\nExpressions and Actions of Envy\\n\u2022\u2022 Doing everything you can to get what the\\nother person has.\\n\u2022\u2022 Working a lot harder than you were to get\\nwhat you want.\\n\u2022\u2022 Trying to improve yourself and your situation.\\n\u2022\u2022 Taking away or ruining what the other person\\nhas.\\n\u2022\u2022 Attacking or criticizing the other person.\\n\u2022\u2022 Doing something to get even.\\n\u2022\u2022 Doing something to make the other person\\nfail or lose what he or she has.\\n\u2022\u2022 Saying mean things about the other person\\nor making the person look bad to others.\\n\u2022\u2022 Trying to show the other person up, to look\\nbetter than the other person.\\n\u2022\u2022 Avoiding persons who have what you want.\\n\u2022\u2022 Other:\\nAftereffects of Envy\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Attending only to what others have that you\\ndon\u2019t.\\n\u2022\u2022 Ruminating when others have had more than\\nyou.\\n\u2022\u2022 Discounting what you do have; not\\nappreciating things you have or things others\\ndo for you.\\n\u2022\u2022 Ruminating about what you don\u2019t have.\\n\u2022\u2022 Making resolutions to change.\\n\u2022\u2022 Other: (continued on next page) Emotion Regulation Handout 6 (p. 4 of 10)\\nFear Words\\nfear\\ndread\\nhorror\\nnervousness\\nshock\\nuneasiness\\nanxiety\\nedginess\\nhysteria\\noverwhelmed\\ntenseness\\nworry\\napprehension\\nfright\\njumpiness\\npanic\\nterror\\nPrompting Events for Feeling Fear\\n\u2022\u2022 Having your life, your health, or your well-\\nbeing threatened.\\n\u2022\u2022 Being in the same situation (or a similar one)\\nwhere you have been threatened or gotten\\nhurt in the past, or where painful things have\\nhappened.\\n\u2022\u2022 Flashbacks.\\n\u2022\u2022 Being in situations where you have seen\\nothers threatened or be hurt.\\n\u2022\u2022 Silence.\\n\u2022\u2022 Being in a new or unfamiliar situation.\\n\u2022\u2022 Being alone (e.g., walking alone, being home\\nalone, living alone).\\n\u2022\u2022 Being in the dark.\\n\u2022\u2022 Being in crowds.\\n\u2022\u2022 Leaving your home.\\n\u2022\u2022 Having to perform in front of others.\\n\u2022\u2022 Pursuing your dreams.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Fear\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You might die, or you are going to die.\\n\u2022\u2022 You might be hurt or harmed.\\n\u2022\u2022 You might lose something valuable.\\n\u2022\u2022 Someone might reject, criticize, or dislike\\nyou.\\n\u2022\u2022 You will embarrass yourself.\\n\u2022\u2022 Failure is possible; expecting to fail.\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You will not get help you want or need.\\n\u2022\u2022 You might lose help you already have.\\n\u2022\u2022 You might lose someone important.\\n\u2022\u2022 You might lose something you want.\\n\u2022\u2022 You are helpless or are losing a sense of\\ncontrol.\\n\u2022\u2022 You are incompetent or are losing mastery.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Fear\\n\u2022\u2022 Breathlessness.\\n\u2022\u2022 Fast heartbeat.\\n\u2022\u2022 Choking sensation, lump in throat.\\n\u2022\u2022 Muscles tensing, cramping.\\n\u2022\u2022 Clenching teeth.\\n\u2022\u2022 Urge to scream or call out.\\n\u2022\u2022 Feeling nauseated.\\n\u2022\u2022 Getting cold; feeling clammy.\\n\u2022\u2022 Feeling your hairs standing on end.\\n\u2022\u2022 Feeling of \u201cbutterflies\u201d in stomach.\\n\u2022\u2022 Wanting to run away or avoid things.\\n\u2022\u2022 Other:\\nExpressions and Actions of Fear\\n\u2022\u2022 Fleeing, running away.\\n\u2022\u2022 Running or walking hurriedly.\\n\u2022\u2022 Hiding from or avoiding what you fear.\\n\u2022\u2022 Engaging in nervous, fearful talk.\\n\u2022\u2022 Pleading or crying for help.\\n\u2022\u2022 Talking less or becoming speechless.\\n\u2022\u2022 Screaming or yelling.\\n\u2022\u2022 Darting eyes or quickly looking around.\\n\u2022\u2022 Frozen stare.\\n\u2022\u2022 Talking yourself out of doing what you fear.\\n\u2022\u2022 Freezing, or trying not to move.\\n\u2022\u2022 Crying or whimpering.\\n\u2022\u2022 Shaking, quivering, or trembling.\\n\u2022\u2022 A shaky or trembling voice.\\n\u2022\u2022 Sweating or perspiring.\\n\u2022\u2022 Diarrhea, vomiting.\\n\u2022\u2022 Hair erect.\\n\u2022\u2022 Other:\\nAftereffects of Fear\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Being hypervigilant to threat.\\n\u2022\u2022 Losing your ability to focus or becoming\\ndisoriented or dazed.\\n\u2022\u2022 Losing control.\\n\u2022\u2022 Imagining the possibility of more loss or\\nfailure.\\n\u2022\u2022 Isolating yourself.\\n\u2022\u2022 Ruminating about other threatening times.\\n\u2022\u2022 Other:\\n(continued on next page) Emotion Regulation Handout 6 (p. 5 of 10)\\nHappiness Words\\nhappiness\\nsatisfaction\\njoviality\\nexhilaration\\necstasy\\njoy\\nbliss\\ntriumph\\noptimism\\ngladness\\nenjoyment\\nenthusiasm\\ncontentment\\nzest\\npride\\nrelief\\njolliness\\nexcitement\\neagerness\\nelation\\namusement\\nthrill\\njubilation\\ngaiety\\nglee\\nenthrallment\\ncheerfulness\\nzaniness\\npleasure\\nrapture\\nhope\\neuphoria\\ndelight\\nzeal\\nPrompting Events for Feeling Happiness\\n\u2022\u2022 Receiving a wonderful surprise.\\n\u2022\u2022 Reality exceeding your expectations.\\n\u2022\u2022 Getting what you want.\\n\u2022\u2022 Getting something you have worked hard for\\nor worried about.\\n\u2022\u2022 Things turning out better than you thought\\nthey would.\\n\u2022\u2022 Being successful at a task.\\n\u2022\u2022 Achieving a desirable outcome.\\n\u2022\u2022 Receiving esteem, respect, or praise.\\n\u2022\u2022 Receiving love, liking, or affection.\\n\u2022\u2022 Being accepted by others.\\n\u2022\u2022 Belonging somewhere or with someone or a\\ngroup.\\n\u2022\u2022 Being with or in contact with people who love\\nor like you.\\n\u2022\u2022 Having very pleasurable sensations.\\n\u2022\u2022 Doing things that create or bring to mind\\npleasurable sensations.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Happiness\\n\u2022\u2022 Interpreting joyful events just as they are, without adding or subtracting.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Happiness\\n\u2022\u2022 Feeling excited.\\n\u2022\u2022 Feeling physically energetic, active.\\n\u2022\u2022 Feeling like giggling or laughing.\\n\u2022\u2022 Feeling your face flush.\\n\u2022\u2022 Feeling calm all the way through.\\n\u2022\u2022 Urge to keep doing what is associated with\\nhappiness.\\n\u2022\u2022 Feeling at peace.\\n\u2022\u2022 Feeling open or expansive.\\n\u2022\u2022 Other:\\nExpressions and Actions of Happiness\\n\u2022\u2022 Smiling.\\n\u2022\u2022 Having a bright, glowing face.\\n\u2022\u2022 Being bouncy or bubbly.\\n\u2022\u2022 Communicating your good feelings.\\n\u2022\u2022 Sharing the feeling.\\n\u2022\u2022 Silliness.\\n\u2022\u2022 Hugging people.\\n\u2022\u2022 Jumping up and down.\\n\u2022\u2022 Saying positive things.\\n\u2022\u2022 Using an enthusiastic or excited voice.\\n\u2022\u2022 Being talkative or talking a lot.\\n\u2022\u2022 Other:\\nAftereffects of Happiness\\n\u2022\u2022 Being courteous or friendly to others.\\n\u2022\u2022 Doing nice things for other people.\\n\u2022\u2022 Having a positive outlook; seeing the bright\\nside.\\n\u2022\u2022 Having a high threshold for worry or\\nannoyance.\\n\u2022\u2022 Remembering and imagining other times you\\nhave felt joyful.\\n\u2022\u2022 Expecting to feel joyful in the future.\\n\u2022\u2022 Other: (continued on next page) Emotion Regulation Handout 6 (p. 6 of 10)\\nJealousy Words\\njealous\\nclutching\\nfear of losing someone/\\nsomething\\nrivalrous\\nwary\\ncautious\\ndefensive\\nsuspicious\\nwatchful\\nclinging\\nmistrustful\\npossessive\\nself-protective\\nPrompting Events for Feeling Jealous\\n\u2022\u2022 An important relationship is threatened or in\\ndanger of being lost.\\n\u2022\u2022 A potential competitor pays attention to\\nsomeone you love.\\n\u2022\u2022 Someone:\\n\u2022\u2022 Is threatening to take away important things\\nin your life.\\n\u2022\u2022 Goes out with the person you like.\\n\u2022\u2022 Ignores you while talking to a friend of\\nyours.\\n\u2022\u2022 Is more attractive, outgoing, or self-\\nconfident than you.\\n\u2022\u2022 You are treated as unimportant by a person\\nyou want to be close to.\\n\u2022\u2022 Your partner tells you that he or she desires\\nmore time alone.\\n\u2022\u2022 Your partner appears to flirt with someone\\nelse.\\n\u2022\u2022 A person you are romantically involved with\\nlooks at someone else.\\n\u2022\u2022 You find the person you love is having an\\naffair with someone else.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Jealousy\\n\u2022\u2022 Believing that:\\n\u2022\u2022 Your partner does not care for you any\\nmore.\\n\u2022\u2022 You are nothing to your partner.\\n\u2022\u2022 Your partner is going to leave you.\\n\u2022\u2022 Your partner is behaving inappropriately.\\n\u2022\u2022 You don\u2019t measure up to your peers.\\n\u2022\u2022 I deserve more than what you are receiving.\\n\u2022\u2022 Believing that:\\n\u2022\u2022 You were cheated.\\n\u2022\u2022 No one cares about you.\\n\u2022\u2022 Your rival is possessive and competitive.\\n\u2022\u2022 Your rival is insecure.\\n\u2022\u2022 Your rival is envious.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Jealousy\\n\u2022\u2022 Breathlessness.\\n\u2022\u2022 Fast heartbeat.\\n\u2022\u2022 Choking sensation, lump in throat.\\n\u2022\u2022 Muscles tensing.\\n\u2022\u2022 Teeth clenching.\\n\u2022\u2022 Becoming suspicious of others.\\n\u2022\u2022 Having injured pride.\\n\u2022\u2022 Feelings of rejection.\\n\u2022\u2022 Needing to be in control.\\n\u2022\u2022 Feeling helpless.\\n\u2022\u2022 Wanting to grasp or keep hold of what you\\nhave.\\n\u2022\u2022 Wanting to push away or eliminate your rival.\\nExpressions and Actions of Jealousy\\n\u2022\u2022 Violent behavior or threats of violence toward\\nthe person threatening to take something\\naway.\\n\u2022\u2022 Attempting to control the freedom of the\\nperson you are afraid of losing.\\n\u2022\u2022 Verbal accusations of disloyalty or\\nunfaithfulness.\\n\u2022\u2022 Spying on the person.\\n\u2022\u2022 Interrogating the person; demanding\\naccounting of time or activities.\\n\u2022\u2022 Collecting evidence of wrongdoings.\\n\u2022\u2022 Clinging; enhanced dependency.\\n\u2022\u2022 Increased or excessive demonstrations of\\nlove.\\n\u2022\u2022 Other:\\nAftereffects of Jealousy\\n\u2022\u2022 Narrowing of attention.\\n\u2022\u2022 Seeing the worst in others.\\n\u2022\u2022 Being mistrustful across the board.\\n\u2022\u2022 Being hypervigilant to threats to your\\nrelationships.\\n\u2022\u2022 Becoming isolated or withdrawn.\\n\u2022\u2022 Other: (continued on next page) Emotion Regulation Handout 6 (p. 7 of 10)\\nLove Words\\nlove\\nattraction\\nenchantment\\nlimerence\\nsympathy\\nadoration\\ncaring\\nfondness\\nlonging\\ntenderness\\naffection\\ncharmed\\ninfatuation\\nlust\\nwarmth\\narousal\\ncompassion\\nkindness\\npassion\\ndesire\\nliking\\nsentimentality\\nPrompting Events for Feeling Love\\n\u2022\u2022 A person:\\n\u2022\u2022 Offers or gives you something you want,\\nneed, or desire.\\n\u2022\u2022 Does things you want or need.\\n\u2022\u2022 Does things you particularly value or\\nadmire.\\n\u2022\u2022 Feeling physically attracted to someone.\\n\u2022\u2022 Being with someone you have fun with.\\n\u2022\u2022 You spend a lot of time with a person.\\n\u2022\u2022 You share a special experience with a\\nperson.\\n\u2022\u2022 You have exceptionally good communication\\nwith a person.\\n\u2022\u2022 Other: Interpretations of Events That Prompt Feelings of Love\\n\u2022\u2022 Believing that a person loves, needs, or appreciates you.\\n\u2022\u2022 Thinking that a person is physically attractive.\\n\u2022\u2022 Judging a person\u2019s personality as wonderful, pleasing, or attractive.\\n\u2022\u2022 Believing that a person can be counted on, or will always be there for you.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Love\\n\u2022\u2022 When you are with or thinking about\\nsomeone:\\n\u2022\u2022 Feeling excited and full of energy.\\n\u2022\u2022 Fast heartbeat.\\n\u2022\u2022 Feeling self-confident.\\n\u2022\u2022 Feeling invulnerable.\\n\u2022\u2022 Feeling happy, joyful, or exuberant.\\n\u2022\u2022 Feeling warm, trusting, and secure.\\n\u2022\u2022 Feeling relaxed and calm.\\n\u2022\u2022 Wanting the best for a person.\\n\u2022\u2022 Wanting to give things to a person.\\n\u2022\u2022 Wanting to see and spend time with a person.\\n\u2022\u2022 Wanting to spend your life with a person.\\n\u2022\u2022 Wanting physical closeness or sex.\\n\u2022\u2022 Wanting emotional closeness. Expressions and Actions of Love\\n\u2022\u2022 Saying \u201cI love you.\u201d\\n\u2022\u2022 Expressing positive feelings to a person.\\n\u2022\u2022 Eye contact, mutual gaze.\\n\u2022\u2022 Touching, petting, hugging, holding, cuddling.\\n\u2022\u2022 Sexual activity.\\n\u2022\u2022 Smiling.\\n\u2022\u2022 Sharing time and experiences with someone.\\n\u2022\u2022 Doing things that the other person wants or\\nneeds.\\n\u2022\u2022 Other:\\nAftereffects of Love\\n\u2022\u2022 Only seeing a person\u2019s positive side.\\n\u2022\u2022 Feeling forgetful or distracted; daydreaming.\\n\u2022\u2022 Feeling openness and trust.\\n\u2022\u2022 Feeling \u201calive,\u201d capable.\\n\u2022\u2022 Remembering other people you have loved.\\n\u2022\u2022 Remembering other people who have loved\\nyou.\\n\u2022\u2022 Remembering other positive events.\\n\u2022\u2022 Believing in yourself; believing you are\\nwonderful, capable, competent.\\n\u2022\u2022 Other:\\n(continued on next page) Emotion Regulation Handout 6 (p. 8 of 10)\\nSadness Words\\nsadness\\ndisappointment\\npity\\ncrushed\\ndisconnected\\ndepression\\ndespair\\nhomesickness\\nanguish\\ndispleasure\\nsuffering\\nglumness\\ngrief\\nneglect\\ndismay\\ninsecurity\\ndejection\\nmelancholy\\nmisery\\nalienation\\nhurt\\nsorrow\\ngloom\\nalone\\nagony\\ndiscontentment\\nrejection\\ndefeat\\nloneliness\\nwoe\\ndi\\u0007straught\\nunhappiness\\nPrompting Events for Feeling Sadness\\n\u2022\u2022 Losing something or someone irretrievably.\\n\u2022\u2022 The death of someone you love.\\n\u2022\u2022 Things not being what you expected or\\nwanted.\\n\u2022\u2022 Things being worse than you expected.\\n\u2022\u2022 Being separated from someone you care for.\\n\u2022\u2022 Getting what you don\u2019t want.\\n\u2022\u2022 Not getting what you have worked for.\\n\u2022\u2022 Not getting what you believe you need in life.\\n\u2022\u2022 Being rejected, disapproved of, or excluded.\\n\u2022\u2022 Discovering that you are powerless or\\nhelpless.\\n\u2022\u2022 Being with someone else who is sad or in\\npain.\\n\u2022\u2022 Reading or hearing about other people\u2019s\\nproblems or troubles in the world.\\n\u2022\u2022 Being alone, or feeling isolated or like an\\noutsider.\\n\u2022\u2022 Thinking about everything you have not\\ngotten.\\n\u2022\u2022 Thinking about your losses.\\n\u2022\u2022 Thinking about missing someone.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Sadness\\n\u2022\u2022 Believing that a separation from someone will\\nlast for a long time or will never end.\\n\u2022\u2022 Believing that you will not get what you want\\nor need in your life.\\n\u2022\u2022 Seeing things or your life as hopeless.\\n\u2022\u2022 Believing that you are worthless or not\\nvaluable.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Sadness\\n\u2022\u2022 Feeling tired, run down, or low in energy.\\n\u2022\u2022 Feeling lethargic, listless; wanting to stay in\\nbed all day.\\n\u2022\u2022 Feeling as if nothing is pleasurable any more.\\n\u2022\u2022 Pain or hollowness in your chest or gut.\\n\u2022\u2022 Feeling empty.\\n\u2022\u2022 Feeling as if you can\u2019t stop crying, or if you\\never start crying you will never be able to\\nstop.\\n\u2022\u2022 Difficulty swallowing.\\n\u2022\u2022 Breathlessness.\\n\u2022\u2022 Dizziness.\\n\u2022\u2022 Other:\\nExpressions and Actions of Sadness\\n\u2022\u2022 Avoiding things.\\n\u2022\u2022 Acting helpless; staying in bed; being\\ninactive.\\n\u2022\u2022 Moping, brooding, or acting moody.\\n\u2022\u2022 Making slow, shuffling movements.\\n\u2022\u2022 Withdrawing from social contact.\\n\u2022\u2022 Avoiding activities that used to bring pleasure.\\n\u2022\u2022 Giving up and no longer trying to improve.\\n\u2022\u2022 Saying sad things.\\n\u2022\u2022 Talking little or not at all.\\n\u2022\u2022 Using a quiet, slow, or monotonous voice.\\n\u2022\u2022 Eyes drooping.\\n\u2022\u2022 Frowning, not smiling.\\n\u2022\u2022 Posture slumping.\\n\u2022\u2022 Sobbing, crying, whimpering.\\n\u2022\u2022 Other:\\nAftereffects of Sadness\\n\u2022\u2022 Not being able to remember happy things.\\n\u2022\u2022 Feeling irritable, touchy, or grouchy.\\n\u2022\u2022 Yearning and searching for the thing lost.\\n\u2022\u2022 Having a negative outlook.\\n\u2022\u2022 Blaming or criticizing yourself.\\n\u2022\u2022 Ruminating about sad events in the past.\\n\u2022\u2022 Insomnia.\\n\u2022\u2022 Appetite disturbance, indigestion.\\n\u2022\u2022 Other: (continued on next page) Emotion Regulation Handout 6 (p. 9 of 10)\\nShame Words\\nshame\\nculpability\\nembarrassment\\nmortification\\nshyness\\ncontrition\\ndiscomposure\\nhumiliation\\nself-conscious\\nPrompting Events for Feeling Shame\\n\u2022\u2022 Being rejected by people you care about.\\n\u2022\u2022 Having others find out that you have done\\nsomething wrong.\\n\u2022\u2022 Doing (or feeling or thinking) something\\nthat people you admire believe is wrong or\\nimmoral.\\n\u2022\u2022 Comparing some aspect of yourself or your\\nbehavior to a standard and feeling as if you\\ndo not live up to that standard.\\n\u2022\u2022 Being betrayed by a person you love.\\n\u2022\u2022 Being laughed at/made fun of.\\n\u2022\u2022 Being criticized in public/in front of someone\\nelse; remembering public criticism.\\n\u2022\u2022 Others attacking your integrity.\\n\u2022\u2022 Being reminded of something wrong,\\nimmoral, or \u201cshameful\u201d you did in the past.\\n\u2022\u2022 Being rejected or criticized for something you\\nexpected praise for.\\n\u2022\u2022 Having emotions/experiences that have been\\ninvalidated.\\n\u2022\u2022 Exposure of a very private aspect of yourself\\nor your life.\\n\u2022\u2022 Exposure of a physical characteristic you\\ndislike.\\n\u2022\u2022 Failing at something you feel you are (or\\nshould be) competent to do.\\n\u2022\u2022 Other:\\nInterpretations of Events That Prompt Feelings of Shame\\n\u2022\u2022 Believing that others will reject you (or have\\nrejected you).\\n\u2022\u2022 Judging yourself to be inferior, not \u201cgood\\nenough,\u201d not as good as others; self-\\ninvalidation.\\n\u2022\u2022 Comparing yourself to others and thinking\\nthat you are a \u201closer.\u201d\\n\u2022\u2022 Believing yourself unlovable.\\n\u2022\u2022 Thinking that you are bad, immoral, or wrong.\\n\u2022\u2022 Thinking that you are defective.\\n\u2022\u2022 Thinking that you are a bad person or a\\nfailure.\\n\u2022\u2022 Believing your body (or a body part) is too\\nbig, too small, or ugly.\\n\u2022\u2022 Thinking that you have not lived up to others\u2019\\nexpectations of you.\\n\u2022\u2022 Thinking that your behavior, thoughts, or\\nfeelings are silly or stupid.\\n\u2022\u2022 Other:\\nBiological Changes and Experiences of Shame\\n\u2022\u2022 Pain in the pit of the stomach.\\n\u2022\u2022 Sense of dread.\\n\u2022\u2022 Wanting to shrink down and/or disappear.\\n\u2022\u2022 Wanting to hide or cover your face and body.\\n\u2022\u2022 Other:\\nExpressions and Actions of Shame\\n\u2022\u2022 Hiding behavior or a characteristic from other\\npeople.\\n\u2022\u2022 Avoiding the person you have harmed.\\n\u2022\u2022 Avoiding persons who have criticized you.\\n\u2022\u2022 Avoiding yourself\u2014distracting, ignoring.\\n\u2022\u2022 Withdrawing; covering the face.\\n\u2022\u2022 Bowing your head, groveling.\\n\u2022\u2022 Appeasing; saying you are sorry over and\\nover and over.\\n\u2022\u2022 Looking down and away from others.\\n\u2022\u2022 Sinking back; slumped and rigid posture.\\n\u2022\u2022 Halting speech; lowered volume while talking.\\n\u2022\u2022 Other:\\nAftereffects of Shame\\n\u2022\u2022 Avoiding thinking about your transgression;\\nshutting down; blocking all emotions.\\n\u2022\u2022 Engaging in distracting, impulsive behaviors\\nto divert your mind or attention.\\n\u2022\u2022 High amount of \u201cself-focus\u201d; preoccupation\\nwith yourself.\\n\u2022\u2022 Depersonalization, dissociative experiences,\\nnumbness, or shock.\\n\u2022\u2022 Attacking or blaming others.\\n\u2022\u2022 Conflicts with other people.\\n\u2022\u2022 Isolation, feeling alienated.\\n\u2022\u2022 Impairment in problem-solving ability.\\n\u2022\u2022 Other: (continued on next page)\"]},\"source_pdf\":\"DBT Skills Workbook.pdf\",\"related_references\":[\"Emotion Regulation Worksheets 4, 4a\"],\"ourspace_kindness_pass\":{\"schema_name\":\"ourspace_dbt_adhd_kindness_pass\",\"schema_version\":\"1.0.0\",\"generated_at_utc\":\"2026-06-25T21:00:29.329839+00:00\",\"shared_library\":true,\"routine_cadence\":\"daily\",\"source_relative_path\":\"04_DBT_Emotion_Regulation/handouts/json/emotion_regulation_handout_6_ways_to_describe_emotions_anger_words_anger_bitterness.json\",\"title\":\"Ways to Describe Emotions Anger Words anger bitterness\",\"category\":\"DBT Emotion Regulation\",\"source_type\":\"handout\",\"disability_profile_basis\":{\"william\":{\"main_doability_needs\":[\"bed-level or seated options by default\",\"oxygen/breathing, pain, vertigo, fatigue, mobility, and recovery time respected\",\"ADHD/autism supports: transitions, low-stimulation starts, tiny visible steps\",\"partial completion and stopping before a crash count as success\",\"no shame, no body blame, no pressure to push through pain or dysphoria\"],\"care_language\":\"direct, validating, masculine, autonomy-preserving, privacy-respecting\"},\"jasper\":{\"main_doability_needs\":[\"ADHD transition support before task demands\",\"caregiver burnout recovery treated as care, not avoidance\",\"protected rest, boundaries, decompression, sensory needs, and people-pleasing checks\",\"low-energy, one-field, one-minute versions allowed\",\"no assumption that Jasper has unlimited caregiver capacity\"],\"care_language\":\"they/them, body-neutral, consent-based, non-shaming, burnout-aware\"},\"shared\":{\"household_rules\":[\"no hour block may hold more than two tasks/tools\",\"skills may be used as one-breath or one-field versions\",\"survival days load critical care first and skip optional worksheets\",\"rest, boundaries, decompression, and asking for help count as care\",\"skills are for support, not grades\"]}},\"universal_kindness_rules\":[\"This is a support tool, not a test.\",\"One line, one checkbox, one breath, or one tiny step counts.\",\"Skipping a skill because the body is unsafe, exhausted, dysregulated, or overloaded is allowed.\",\"Do not stack this with more than one other task inside the same hour.\",\"Survival-day version always wins over perfection.\"],\"william_accessibility_adaptations\":[\"Use bed-level, seated, voice-note, or caregiver-assisted versions when needed.\",\"Avoid pain escalation, respiratory strain, unsafe transfers, and dysphoria-triggering language.\",\"Break worksheets into one-field chunks; stopping before a crash is success.\"],\"jasper_accessibility_adaptations\":[\"Start with transition support before expecting focus.\",\"Protect caregiver burnout recovery; rest and boundaries are valid completion.\",\"Use body-doubling, timers, low-stimulation versions, and one-minute starts.\"],\"tiny_steps\":[\"Read one short section.\",\"Choose one sentence or tool that fits today.\",\"Use the low-spoon version; no full worksheet is required.\"],\"routine_integration\":{\"routine_role\":\"small daily support option\",\"start_the_day_use\":\"eligible as a rotating daily skill, never more than one DBT/ADHD skill in an hour block\",\"recommended_block\":\"after body check or before decompression\"},\"completion_rules\":{\"partial_completion_counts\":true,\"can_be_paused_and_resumed\":true,\"no_shame_if_skipped\":true,\"low_spoon_version_required\":true,\"can_be_done_separately_by_william_and_jasper\":true,\"can_be_done_together_only_if_both_people_have_capacity\":true},\"schedule_policy\":{\"start_the_day_eligible\":true,\"expanded_day_eligible\":true,\"max_items_per_hour_block\":2,\"do_not_force_into_day\":false,\"do_not_stack_with\":[\"appointment\",\"heavy_chore\",\"conflict_repair\",\"hygiene_overload\",\"caregiver_overload\"]},\"currency_suggestion\":{\"platinum\":0,\"gold\":0,\"silver\":3,\"copper\":0}},\"id\":{\"_merged_values\":[\"emotion_regulation_handout_6\",\"emotion-regulation-handout-6\"]},\"ourspace_shared_life_filter\":{\"revision_id\":\"ourspace_shared_life_filter_v1\",\"title\":\"Ways to Describe Emotions Anger Words anger bitterness\",\"domain\":\"emotion_regulation\",\"item_type\":\"handout\",\"shared_facing_summary\":\"Emotion work starts with the body and access needs. Hunger, pain, oxygen, sleep attacks, MCAS reactions, trauma cues, and exhaustion count.\",\"tiny_steps\":[\"Name the emotion.\",\"Check body basics: breathing, pain, food/water, meds, temperature, sensory load.\",\"Lower the demand by one size.\",\"Choose soothe, solve, pause, or ask for help.\"],\"flare_day_versions\":{\"minimum\":\"One breath, one label, one safe message, or one checkbox.\",\"medium\":\"Two to five minutes with everything reachable from bed/chair.\",\"full\":\"Use the original worksheet/handout when both bodies and brains have capacity.\"},\"accessibility_modifications\":[\"Use low-exertion regulation first.\",\"Allow anger and grief without turning them into shame.\",\"Track patterns without moral judgment.\"],\"relationship_and_caregiver_notes\":[\"William's needs and Jasper's capacity both count.\",\"Ask before helping; ask before escalating; name the smallest next step.\",\"Pause means pause, not abandonment. I am coming back. I care about us. I need a smaller next step.\",\"What is needed, what capacity exists, what can be smaller, and what can wait?\"],\"identity_and_trauma_filter\":[\"Use William's masculine language and Jasper's they/them language.\",\"Use consent-based, non-shaming, body-neutral language unless a person has explicitly chosen a term.\",\"Do not turn symptoms, dysphoria, trauma responses, clutter, fatigue, or emotional intensity into moral failure.\"],\"avoid_or_adjust\":[\"Do not demand immediate calm during respiratory distress, pain flares, dissociation, or overload.\"],\"suggested_cadence\":[\"daily_optional\",\"flare_day_as_needed\"],\"app_tags\":[\"adhd_friendly\",\"disability_first\",\"emotion_regulation\",\"shared\",\"tiny_steps\",\"trauma_informed\"]},\"item_type\":\"handout\",\"is_example\":false,\"source_book_pages\":[\"214\",\"215\",\"216\",\"217\",\"218\",\"219\",\"220\",\"221\",\"222\"],\"title\":\"Ways to Describe Emotions Anger Words anger bitterness\",\"module_category\":\"Emotion Regulation Skills\",\"shared_json_path\":\"shared/04_dbt_emotion_regulation/handouts_json/emotion_regulation_handout_6_ways_to_describe_emotions_anger_words_anger_26020865.json\",\"module\":\"Emotion Regulation\",\"keywords\":[\"Anger\",\"Describe\",\"Emotions\",\"Ways\",\"Words\",\"anger\",\"bitterness\"]}}");
